INSERT INTO questions (professions, course, topic, category, subtopic, difficulty, question_type, question_text, options, correct_answer, explanation, region, high_yield, year_level, source_reference) VALUES
('{"medicine"}','Medicine','Reproductive System & OB-GYN','Clinicals','Antenatal Care & Normal Pregnancy','easy','flashcard','What investigations are performed at the antenatal booking visit?','["Blood group and Rhesus typing, FBC (anaemia screen), VDRL/RPR (syphilis), HIV test, hepatitis B surface antigen, rubella immune status, urine dipstick/MSU, blood pressure, BMI, and booking ultrasound for dating and nuchal translucency if 11–13+6 weeks."]','A','Additional investigations may include haemoglobin electrophoresis (sickle cell/thalassaemia screening), malaria blood film in endemic areas, and blood glucose screening. All women should be offered first-trimester combined screening for chromosomal anomalies.','universal',true,'{year1,year2,year3,year4,year5,year6,practitioner}','Harrison''s Principles of Internal Medicine 20th Ed');
INSERT INTO questions (professions, course, topic, category, subtopic, difficulty, question_type, question_text, options, correct_answer, explanation, region, high_yield, year_level, source_reference) VALUES
('{"medicine"}','Medicine','Reproductive System & OB-GYN','Clinicals','Antenatal Care & Normal Pregnancy','easy','flashcard','What is Naegele''s rule for calculating the estimated date of delivery (EDD)?','["Add 9 months and 7 days to the first day of the last menstrual period (LMP). Alternatively: add 1 year, subtract 3 months, add 7 days. This assumes a regular 28-day cycle with ovulation on day 14. Gestation is 280 days (40 weeks) from LMP."]','A','If cycle length differs from 28 days, adjust accordingly: add the difference in days (e.g., for a 35-day cycle, add an extra 7 days to the EDD). Ultrasound dating by CRL is more accurate and should be used if the LMP is uncertain or ultrasound dating differs significantly.','universal',true,'{year1,year2,year3,year4,year5,year6,practitioner}','Harrison''s Principles of Internal Medicine 20th Ed');
INSERT INTO questions (professions, course, topic, category, subtopic, difficulty, question_type, question_text, options, correct_answer, explanation, region, high_yield, year_level, source_reference) VALUES
('{"medicine"}','Medicine','Reproductive System & OB-GYN','Clinicals','Antenatal Care & Normal Pregnancy','medium','flashcard','What are the components of the biophysical profile (BPP) and how is it scored?','["Five components each scored 0 or 2: (1) Fetal breathing movements (≥1 episode of ≥30 seconds in 30 minutes), (2) Fetal movement (≥3 discrete body/limb movements in 30 minutes), (3) Fetal tone (≥1 episode of active extension with return to flexion), (4) Amniotic fluid volume (deepest vertical pocket ≥2 cm), (5) Non-stress test (NST) — reactive cardiotocograph. Maximum score 10; ≥8 is normal, 6 equivocal, ≤4 requires urgent intervention."]','A','A modified BPP uses NST + amniotic fluid volume only. BPP is used for fetal surveillance in high-risk pregnancies (post-term, IUGR, pre-eclampsia, GDM). False-negative rate is very low (<1/1000 within 1 week of normal BPP).','universal',true,'{year1,year2,year3,year4,year5,year6,practitioner}','Harrison''s Principles of Internal Medicine 20th Ed');
INSERT INTO questions (professions, course, topic, category, subtopic, difficulty, question_type, question_text, options, correct_answer, explanation, region, high_yield, year_level, source_reference) VALUES
('{"medicine"}','Medicine','Reproductive System & OB-GYN','Clinicals','Antenatal Care & Normal Pregnancy','medium','flashcard','When is anti-D prophylaxis given to Rh-negative women during pregnancy?','["Routine antenatal anti-D immunoglobulin (RAADP): 500 IU IM at 28 weeks (and 34 weeks in two-dose schedule). Also after any sensitising event: chorionic villus sampling, amniocentesis, antepartum haemorrhage, external cephalic version, abdominal trauma, miscarriage, or ectopic pregnancy. Postpartum: 500 IU IM within 72 hours if baby is Rh-positive."]','A','Kleihauer-Betke test estimates the volume of fetomaternal haemorrhage; additional anti-D doses are required if haemorrhage >4 mL fetal RBCs. Anti-D is immunoglobulin G that destroys fetal Rh-positive cells before maternal sensitisation can occur.','universal',true,'{year1,year2,year3,year4,year5,year6,practitioner}','Harrison''s Principles of Internal Medicine 20th Ed');
INSERT INTO questions (professions, course, topic, category, subtopic, difficulty, question_type, question_text, options, correct_answer, explanation, region, high_yield, year_level, source_reference) VALUES
('{"medicine"}','Medicine','Reproductive System & OB-GYN','Clinicals','Antenatal Care & Normal Pregnancy','easy','flashcard','What supplements are recommended routinely in pregnancy?','["Folic acid 400 mcg/day (started pre-conception and continued to 12 weeks) to prevent neural tube defects. Women at high risk (previous NTD, epilepsy on valproate/carbamazepine, BMI >30, malabsorption) need 5 mg/day. Vitamin D 400 IU/day throughout pregnancy. Iron supplementation if anaemic. Iodine is recommended in some guidelines."]','A','Folic acid reduces NTD risk by 70%. Vitamin D deficiency is common and linked to pre-eclampsia, fetal bone disease, and neonatal hypocalcaemia. Vitamin A >700 mcg/day (or retinol supplements) is teratogenic and should be avoided in pregnancy.','universal',true,'{year1,year2,year3,year4,year5,year6,practitioner}','Harrison''s Principles of Internal Medicine 20th Ed');
INSERT INTO questions (professions, course, topic, category, subtopic, difficulty, question_type, question_text, options, correct_answer, explanation, region, high_yield, year_level, source_reference) VALUES
('{"medicine"}','Medicine','Reproductive System & OB-GYN','Clinicals','Antenatal Care & Normal Pregnancy','medium','flashcard','What are the normal physiological changes in cardiovascular parameters during pregnancy?','["Cardiac output increases by 40–50% (by 24 weeks), due to increased heart rate (+15–20 bpm) and stroke volume (+30%). Blood pressure falls in first and second trimesters due to decreased systemic vascular resistance (progesterone-mediated vasodilation), reaching nadir at 20–24 weeks, then returns to baseline by term. Blood volume increases by 40–50%. Plasma volume increases more than red cell mass, causing physiological anaemia of pregnancy."]','A','These changes can unmask or worsen pre-existing cardiac disease. The most haemodynamically stressful time for the heart is 28–32 weeks and peripartum. Aortocaval compression in supine position reduces cardiac output and should be avoided — women should lie in left lateral position.','universal',false,'{year1,year2,year3,year4,year5,year6,practitioner}','Harrison''s Principles of Internal Medicine 20th Ed');
INSERT INTO questions (professions, course, topic, category, subtopic, difficulty, question_type, question_text, options, correct_answer, explanation, region, high_yield, year_level, source_reference) VALUES
('{"medicine"}','Medicine','Reproductive System & OB-GYN','Clinicals','Antenatal Care & Normal Pregnancy','medium','flashcard','What is the screening programme for Group B Streptococcus (GBS) in pregnancy?','["Two approaches: (1) Universal screening — vaginal/rectal swab at 35–37 weeks; positive culture triggers intrapartum IV antibiotic prophylaxis (penicillin G). (2) Risk-based approach (UK) — give IAP if: GBS bacteriuria in current pregnancy, previous GBS-affected baby, intrapartum fever, preterm labour, PPROM. No routine antenatal screening in UK; USA uses universal screening."]','A','GBS causes early-onset neonatal sepsis (within 7 days), pneumonia, and meningitis. Penicillin G is first-line for IAP; clindamycin for penicillin allergy (if susceptible). Vaginal GBS colonisation in pregnancy does not require treatment antenatally — only intrapartum prophylaxis matters.','universal',true,'{year1,year2,year3,year4,year5,year6,practitioner}','Harrison''s Principles of Internal Medicine 20th Ed');
INSERT INTO questions (professions, course, topic, category, subtopic, difficulty, question_type, question_text, options, correct_answer, explanation, region, high_yield, year_level, source_reference) VALUES
('{"medicine"}','Medicine','Reproductive System & OB-GYN','Clinicals','Antenatal Care & Normal Pregnancy','hard','flashcard','How is intrauterine growth restriction (IUGR) classified and what causes it?','["IUGR is classified as: Symmetrical (global) — head and body equally small, usually early onset, often due to chromosomal anomalies, congenital infection (TORCH), or severe early nutritional deficiency. Asymmetrical — head spared (brain-sparing), body small, late onset, usually due to uteroplacental insufficiency (pre-eclampsia, chronic hypertension, smoking, antiphospholipid syndrome). SGA is defined as EFW or AC below 10th centile; severe SGA is below 3rd centile."]','A','Umbilical artery Doppler is used to monitor IUGR. Absent or reversed end-diastolic flow indicates critical placental insufficiency. Timing of delivery balances gestational maturity vs risk of intrauterine death. IUGR babies are at risk of neonatal polycythaemia, hypoglycaemia, hypothermia, and meconium aspiration.','universal',true,'{year1,year2,year3,year4,year5,year6,practitioner}','Harrison''s Principles of Internal Medicine 20th Ed');
INSERT INTO questions (professions, course, topic, category, subtopic, difficulty, question_type, question_text, options, correct_answer, explanation, region, high_yield, year_level, source_reference) VALUES
('{"medicine"}','Medicine','Reproductive System & OB-GYN','Clinicals','Antenatal Care & Normal Pregnancy','hard','flashcard','What is obstetric cholestasis (intrahepatic cholestasis of pregnancy) and how is it managed?','["Obstetric cholestasis (ICP) is liver dysfunction in pregnancy caused by impaired bile acid excretion, presenting with pruritus (particularly palms and soles) without rash, elevated serum bile acids (≥10 μmol/L), elevated transaminases, and no rash. Diagnosed after 28 weeks. Complications: sudden fetal death (due to cardiac arrhythmia from fetal bile acid accumulation), premature labour. Management: ursodeoxycholic acid (UDCA) 10–15 mg/kg/day (reduces symptoms and bile acids), fetal monitoring, elective delivery at 37 weeks."]','A','The risk of sudden intrauterine death increases with bile acids >40 μmol/L. Vitamin K supplementation may be needed if prolonged PT (fat malabsorption). Symptoms resolve after delivery. ICP recurs in ~60–70% of subsequent pregnancies.','universal',false,'{year1,year2,year3,year4,year5,year6,practitioner}','Harrison''s Principles of Internal Medicine 20th Ed');
INSERT INTO questions (professions, course, topic, category, subtopic, difficulty, question_type, question_text, options, correct_answer, explanation, region, high_yield, year_level, source_reference) VALUES
('{"medicine"}','Medicine','Reproductive System & OB-GYN','Clinicals','Antenatal Care & Normal Pregnancy','medium','flashcard','What is the Cardiff kick chart and how is it used in fetal surveillance?','["The Cardiff kick chart is a method of fetal movement counting used in antenatal surveillance. Women are asked to count fetal movements daily and record the time taken to feel 10 movements (in the Cardiff count-to-ten method). Concern arises if the woman does not perceive 10 movements within 12 hours (some protocols use 10 in 2 hours). Reduced fetal movement warrants immediate assessment with CTG and possibly BPP/Doppler as it may indicate fetal compromise or impending fetal death."]','A','Any sudden reduction in fetal movement perceived by the mother should be taken seriously. RCOG guidelines recommend that women with reduced fetal movement at term who have a normal CTG should have a growth scan and liquor assessment, as reduced movement may precede fetal compromise by 24–48 hours.','universal',true,'{year1,year2,year3,year4,year5,year6,practitioner}','Harrison''s Principles of Internal Medicine 20th Ed');
INSERT INTO questions (professions, course, topic, category, subtopic, difficulty, question_type, question_text, options, correct_answer, explanation, region, high_yield, year_level, source_reference) VALUES
('{"medicine"}','Medicine','Reproductive System & OB-GYN','Clinicals','Pre-eclampsia & Eclampsia','easy','flashcard','What are the diagnostic criteria for pre-eclampsia?','["New-onset hypertension (BP ≥140/90 mmHg on two readings ≥4 hours apart) after 20 weeks gestation PLUS proteinuria ≥300 mg in 24 hours (or PCR ≥30 mg/mmol or dipstick 2+). OR, in the absence of proteinuria, new-onset: thrombocytopenia (<100 × 10⁹/L), renal impairment (creatinine >96 μmol/L), impaired liver function (transaminases >2× ULN), pulmonary oedema, new headache, or visual disturbance."]','A','Pre-eclampsia is a multisystem disorder of placental origin. Abnormal placentation causes reduced placental perfusion, release of antiangiogenic factors (sFlt-1, endoglin), endothelial dysfunction, and widespread vascular damage. Risk factors: nulliparity, multiple gestation, previous PE, chronic hypertension, diabetes, renal disease, antiphospholipid syndrome.','universal',true,'{year1,year2,year3,year4,year5,year6,practitioner}','Harrison''s Principles of Internal Medicine 20th Ed');
INSERT INTO questions (professions, course, topic, category, subtopic, difficulty, question_type, question_text, options, correct_answer, explanation, region, high_yield, year_level, source_reference) VALUES
('{"medicine"}','Medicine','Reproductive System & OB-GYN','Clinicals','Pre-eclampsia & Eclampsia','medium','flashcard','Describe the Magpie Trial protocol for magnesium sulphate in eclampsia.','["Loading dose: MgSO4 4 g IV infused over 5–15 minutes (in 100 mL normal saline). Maintenance: 1 g/hour IV for 24 hours after the last seizure. If convulsion recurs: further 2–4 g IV over 5 minutes. Monitoring: urine output ≥25 mL/hour, respiratory rate ≥12/minute, deep tendon reflexes present. Antidote for toxicity: calcium gluconate 1 g (10 mL of 10%) IV over 3 minutes."]','A','The Magpie Trial (2002) showed MgSO4 halves the risk of eclampsia and reduces maternal mortality. Magnesium acts by blocking NMDA receptors and causing cerebral vasodilation. Serum levels: therapeutic 2–3.5 mmol/L; loss of reflexes 3.5–5 mmol/L; respiratory arrest >5 mmol/L; cardiac arrest >6–7 mmol/L.','universal',true,'{year1,year2,year3,year4,year5,year6,practitioner}','Harrison''s Principles of Internal Medicine 20th Ed');
INSERT INTO questions (professions, course, topic, category, subtopic, difficulty, question_type, question_text, options, correct_answer, explanation, region, high_yield, year_level, source_reference) VALUES
('{"medicine"}','Medicine','Reproductive System & OB-GYN','Clinicals','Pre-eclampsia & Eclampsia','medium','flashcard','What are the antihypertensive agents used for acute severe hypertension in pregnancy according to Ghana STG?','["First-line options: (1) Hydralazine 5 mg IV slow bolus, repeated every 20 minutes up to 20 mg total; or (2) Labetalol 20 mg IV, followed by 40 mg, then 80 mg every 10 minutes (max 300 mg); or (3) Nifedipine 10 mg orally/sublingually, repeated every 30 minutes if needed (max 30 mg). Target BP: 140–150/90–100 mmHg (avoid sudden drops that compromise placental perfusion)."]','A','Contraindicated: ACE inhibitors and ARBs (fetotoxic), sodium nitroprusside (fetal cyanide toxicity). Methyldopa is safe for chronic hypertension but too slow for acute control. Labetalol is a combined alpha and beta blocker. Nifedipine and MgSO4 combination requires caution (may exacerbate hypotension and neuromuscular blockade).','universal',true,'{year1,year2,year3,year4,year5,year6,practitioner}','Harrison''s Principles of Internal Medicine 20th Ed');
INSERT INTO questions (professions, course, topic, category, subtopic, difficulty, question_type, question_text, options, correct_answer, explanation, region, high_yield, year_level, source_reference) VALUES
('{"medicine"}','Medicine','Reproductive System & OB-GYN','Clinicals','Pre-eclampsia & Eclampsia','hard','flashcard','What is HELLP syndrome and what are its diagnostic criteria?','["HELLP syndrome is a severe variant of pre-eclampsia: Haemolysis (microangiopathic — elevated LDH >600 U/L, low haptoglobin, schistocytes on blood film, bilirubin >20 μmol/L), Elevated Liver enzymes (AST/ALT >70 U/L), Low Platelets (<100 × 10⁹/L). Partial HELLP: one or two features. Mississippi classification: Class 1 (platelets <50), Class 2 (50–100), Class 3 (100–150). Complications: hepatic rupture, DIC, acute renal failure, placental abruption."]','A','Treatment: stabilise (MgSO4, antihypertensives), corticosteroids may improve platelet count transiently, and DELIVER. Platelet transfusion if <20 × 10⁹/L or before caesarean if <50 × 10⁹/L. Hepatic rupture (subcapsular haematoma) is life-threatening: presents with RUQ pain radiating to shoulder; requires surgical haemostasis.','universal',true,'{year1,year2,year3,year4,year5,year6,practitioner}','Harrison''s Principles of Internal Medicine 20th Ed');
INSERT INTO questions (professions, course, topic, category, subtopic, difficulty, question_type, question_text, options, correct_answer, explanation, region, high_yield, year_level, source_reference) VALUES
('{"medicine"}','Medicine','Reproductive System & OB-GYN','Clinicals','Pre-eclampsia & Eclampsia','easy','flashcard','Name four risk factors for developing pre-eclampsia.','["High-risk factors (RR ≥8): previous pre-eclampsia, multifetal pregnancy, chronic hypertension, diabetes mellitus (type 1 or 2), renal disease, autoimmune disease (SLE, antiphospholipid syndrome). Moderate-risk factors (RR ~2): nulliparity, BMI >30, age >40, family history of pre-eclampsia, inter-pregnancy interval >10 years, multiple pregnancy in a new relationship."]','A','The placental growth factor (PlGF) test and uterine artery Doppler pulsatility index at 11–13 weeks (first trimester screening) can predict pre-eclampsia risk with >80% detection. Women with ≥1 high-risk or ≥2 moderate risk factors should receive aspirin 75–150 mg/day from 12–16 weeks to 36 weeks.','universal',true,'{year1,year2,year3,year4,year5,year6,practitioner}','Harrison''s Principles of Internal Medicine 20th Ed');
INSERT INTO questions (professions, course, topic, category, subtopic, difficulty, question_type, question_text, options, correct_answer, explanation, region, high_yield, year_level, source_reference) VALUES
('{"medicine"}','Medicine','Reproductive System & OB-GYN','Clinicals','Pre-eclampsia & Eclampsia','medium','flashcard','What is the emergency management of an eclamptic seizure?','["Immediate steps: (1) Call for help — multidisciplinary team. (2) Left lateral position + high-flow oxygen 15 L/min via facemask. (3) Secure IV access. (4) MgSO4 4 g IV over 5–10 minutes (loading dose). (5) If seizure recurs: MgSO4 2–4 g IV over 5 minutes. (6) Antihypertensives if BP ≥160/110 mmHg. (7) Catheterisation and fluid balance. (8) Continuous fetal monitoring. (9) Deliver once mother is stabilised — mode depends on cervical favourability and fetal condition."]','A','Eclampsia can occur ante-, intra-, or postpartum. ~25–44% of eclamptic seizures occur postpartum (up to 4–6 weeks). Complications: aspiration pneumonia, cerebral haemorrhage, ARDS, acute renal failure, DIC, liver failure. Diazepam is second-line if MgSO4 unavailable but has neonatal respiratory depression risk.','universal',true,'{year1,year2,year3,year4,year5,year6,practitioner}','Harrison''s Principles of Internal Medicine 20th Ed');
INSERT INTO questions (professions, course, topic, category, subtopic, difficulty, question_type, question_text, options, correct_answer, explanation, region, high_yield, year_level, source_reference) VALUES
('{"medicine"}','Medicine','Reproductive System & OB-GYN','Clinicals','Pre-eclampsia & Eclampsia','hard','flashcard','What is the pathophysiology of pre-eclampsia at a molecular level?','["Abnormal placentation: defective trophoblast invasion of spiral arteries → high-resistance uteroplacental circulation → placental ischaemia/hypoxia → release of anti-angiogenic factors (sFlt-1 soluble Fms-like tyrosine kinase-1 and sEndoglin) → these antagonise pro-angiogenic VEGF and PlGF → widespread endothelial dysfunction → hypertension, proteinuria (glomerular endotheliosis), oedema, thrombocytopenia, hepatic inflammation, and cerebral vasospasm (eclampsia)."]','A','sFlt-1:PlGF ratio >38 (or >85 in some labs) has high sensitivity and specificity for diagnosing pre-eclampsia and predicting its development within 4 weeks in women with suspected disease. This ratio is increasingly used in clinical practice as a biomarker.','universal',false,'{year1,year2,year3,year4,year5,year6,practitioner}','Harrison''s Principles of Internal Medicine 20th Ed');
INSERT INTO questions (professions, course, topic, category, subtopic, difficulty, question_type, question_text, options, correct_answer, explanation, region, high_yield, year_level, source_reference) VALUES
('{"medicine"}','Medicine','Reproductive System & OB-GYN','Clinicals','Pre-eclampsia & Eclampsia','medium','flashcard','How does pre-eclampsia affect long-term maternal cardiovascular risk?','["Women with a history of pre-eclampsia have significantly elevated long-term cardiovascular risk: 2-fold increased risk of ischaemic heart disease, stroke, and peripheral vascular disease; 2–8-fold increased risk of hypertension; 3-fold increased risk of developing chronic kidney disease. The risk increases with early-onset (<34 weeks) and severe/recurrent pre-eclampsia. Women should have annual BP check, lipid profile, and fasting glucose postpartum, with lifestyle modification and statin therapy if indicated."]','A','Pre-eclampsia is now recognised as a marker of underlying cardiovascular predisposition (shared pathophysiology with atherosclerosis), not merely a pregnancy-specific complication. It should be disclosed to subsequent healthcare providers as a risk factor for future CVD screening.','universal',false,'{year1,year2,year3,year4,year5,year6,practitioner}','Harrison''s Principles of Internal Medicine 20th Ed');
INSERT INTO questions (professions, course, topic, category, subtopic, difficulty, question_type, question_text, options, correct_answer, explanation, region, high_yield, year_level, source_reference) VALUES
('{"medicine"}','Medicine','Reproductive System & OB-GYN','Clinicals','Pre-eclampsia & Eclampsia','medium','flashcard','What is the difference between gestational hypertension and pre-eclampsia?','["Gestational hypertension: new-onset BP ≥140/90 mmHg after 20 weeks WITHOUT proteinuria or end-organ dysfunction. Pre-eclampsia: new-onset hypertension after 20 weeks WITH proteinuria ≥300 mg/24h OR end-organ features (thrombocytopenia, impaired liver function, renal impairment, pulmonary oedema, new headache/visual disturbance). Gestational hypertension can progress to pre-eclampsia in up to 25% of cases and requires close monitoring. Both resolve by 12 weeks postpartum; if they persist, the diagnosis is chronic hypertension."]','A','Women with gestational hypertension should be monitored with BP checks 2–3× weekly, urine PCR weekly, and blood tests (FBC, U&E, LFTs) weekly. Antihypertensive treatment is initiated if BP consistently ≥150/100 mmHg. Delivery at 37 weeks is recommended for gestational hypertension if on treatment.','universal',true,'{year1,year2,year3,year4,year5,year6,practitioner}','Harrison''s Principles of Internal Medicine 20th Ed');
INSERT INTO questions (professions, course, topic, category, subtopic, difficulty, question_type, question_text, options, correct_answer, explanation, region, high_yield, year_level, source_reference) VALUES
('{"medicine"}','Medicine','Reproductive System & OB-GYN','Clinicals','Pre-eclampsia & Eclampsia','hard','flashcard','What is the role of antenatal corticosteroids in severe pre-eclampsia managed expectantly before 34 weeks?','["Antenatal corticosteroids (betamethasone 12 mg IM × 2 doses 24 hours apart, or dexamethasone 6 mg IM × 4 doses 12 hours apart) are administered to women with severe pre-eclampsia being managed expectantly before 34 weeks to accelerate fetal lung maturity, reducing risk of neonatal RDS, IVH, and NEC. Betamethasone may also temporarily improve platelet count in HELLP syndrome (though this effect is not sustained). Steroids do not treat or reverse pre-eclampsia — delivery remains the only cure."]','A','Expectant management of severe pre-eclampsia before 34 weeks is controversial and should only be undertaken in specialised units with intensive maternal and fetal monitoring. Benefits of delay (fetal lung maturity) must be weighed against risk of maternal deterioration, placental abruption, and IUFD.','universal',true,'{year1,year2,year3,year4,year5,year6,practitioner}','Harrison''s Principles of Internal Medicine 20th Ed');
INSERT INTO questions (professions, course, topic, category, subtopic, difficulty, question_type, question_text, options, correct_answer, explanation, region, high_yield, year_level, source_reference) VALUES
('{"medicine"}','Medicine','Reproductive System & OB-GYN','Clinicals','Obstetric Emergencies','easy','flashcard','What are the 4 Ts of postpartum haemorrhage causes?','["(1) TONE (70–80%): uterine atony — most common cause; managed with oxytocin, ergometrine, carboprost, misoprostol, bimanual compression. (2) TISSUE (10%): retained placenta or products of conception — requires manual removal or curettage. (3) TRAUMA (10%): genital tract lacerations, uterine rupture, haematoma — requires surgical repair. (4) THROMBIN (1%): coagulopathy — DIC, platelet disorders, inherited coagulopathy; requires FFP, cryoprecipitate, platelets, tranexamic acid."]','A','Primary PPH = blood loss ≥500 mL within 24 hours of vaginal delivery (≥1000 mL after caesarean). Secondary PPH = abnormal bleeding 24 hours to 12 weeks postpartum (usually due to retained products or infection). Management of atonic PPH follows a stepwise approach: oxytocin → ergometrine → carboprost → misoprostol → surgical (B-Lynch, uterine artery ligation, UAE, hysterectomy).','universal',true,'{year1,year2,year3,year4,year5,year6,practitioner}','Harrison''s Principles of Internal Medicine 20th Ed');
INSERT INTO questions (professions, course, topic, category, subtopic, difficulty, question_type, question_text, options, correct_answer, explanation, region, high_yield, year_level, source_reference) VALUES
('{"medicine"}','Medicine','Reproductive System & OB-GYN','Clinicals','Obstetric Emergencies','medium','flashcard','Describe the stepwise management of shoulder dystocia using the HELPERR mnemonic.','["H — Call for HELP. E — Evaluate for Episiotomy (only if needed for internal manoeuvres). L — Legs (McRoberts manoeuvre — hyperflexion of maternal thighs onto abdomen). P — Suprapubic Pressure (sustained downward pressure on posterior aspect of anterior fetal shoulder to dislodge it). E — Enter (internal rotational manoeuvres — Rubin II: pressure on posterior aspect of anterior shoulder; Woods screw: pressure on anterior aspect of posterior shoulder). R — Remove the posterior arm (delivery of posterior arm by sweeping it across fetal chest). R — Roll the patient to all-fours (Gaskin manoeuvre)."]','A','Shoulder dystocia occurs in ~0.2–3% of vaginal deliveries, more common with macrosomia, GDM, post-term pregnancy, and previous shoulder dystocia. The turtle sign (retraction of fetal head against maternal perineum after delivery) is the clinical sign. Complications: Erb''s palsy (brachial plexus injury), fractures (clavicle, humerus), neonatal HIE, maternal perineal trauma.','universal',true,'{year1,year2,year3,year4,year5,year6,practitioner}','Harrison''s Principles of Internal Medicine 20th Ed');
INSERT INTO questions (professions, course, topic, category, subtopic, difficulty, question_type, question_text, options, correct_answer, explanation, region, high_yield, year_level, source_reference) VALUES
('{"medicine"}','Medicine','Reproductive System & OB-GYN','Clinicals','Obstetric Emergencies','medium','flashcard','What is uterine inversion and how is it managed?','["Uterine inversion is the inside-out turning of the uterus through the cervix, occurring during third stage of labour (risk factors: fundal placenta, cord traction without uterine support, uterine atony). Classification: incomplete (uterus not beyond cervix), complete (uterus through cervix into vagina), prolapsed (through introitus). Immediate management: (1) Call for help, IV access, resuscitation. (2) Do NOT remove the placenta yet (bleeding worsens). (3) Manual replacement (Johnson technique — push fundus back through cervix). (4) If fails under GA: hydrostatic replacement (O''Sullivan method — saline infusion into vagina), or surgery (Haultain procedure)."]','A','Key: do not attempt placental removal before uterine replacement. Tocolytics (terbutaline, nitric oxide) relax the uterus to facilitate replacement. After replacement, oxytocin is given to maintain uterine tone. Blood transfusion is frequently required. Maternal mortality without prompt treatment is high.','universal',true,'{year1,year2,year3,year4,year5,year6,practitioner}','Harrison''s Principles of Internal Medicine 20th Ed');
INSERT INTO questions (professions, course, topic, category, subtopic, difficulty, question_type, question_text, options, correct_answer, explanation, region, high_yield, year_level, source_reference) VALUES
('{"medicine"}','Medicine','Reproductive System & OB-GYN','Clinicals','Obstetric Emergencies','hard','flashcard','What is amniotic fluid embolism (AFE) and what are its features?','["AFE is a rare, catastrophic obstetric emergency occurring when amniotic fluid or fetal cells enter the maternal circulation, triggering an anaphylactoid or complement-mediated inflammatory response. Classic triad: (1) Acute hypoxia/respiratory failure, (2) Cardiovascular collapse/cardiac arrest, (3) DIC with massive haemorrhage. Occurs during or immediately after delivery. Diagnosis is clinical (exclusion of other causes). Management: CPR, intubation, vasopressors, blood products (FFP, platelets, cryoprecipitate), delivery of fetus if still in utero. Mortality 16–61%."]','A','AFE cannot be predicted or prevented. Survivors often have significant neurological sequelae. Some centres report improved outcomes with a-HA (hydroxocobalamin) or C1-esterase inhibitor. DIC is almost universal in severe AFE; early aggressive haemostatic resuscitation with 1:1:1 (RBC:FFP:platelets) is essential.','universal',true,'{year1,year2,year3,year4,year5,year6,practitioner}','Harrison''s Principles of Internal Medicine 20th Ed');
INSERT INTO questions (professions, course, topic, category, subtopic, difficulty, question_type, question_text, options, correct_answer, explanation, region, high_yield, year_level, source_reference) VALUES
('{"medicine"}','Medicine','Reproductive System & OB-GYN','Clinicals','Obstetric Emergencies','easy','flashcard','What are the clinical features of placental abruption?','["Placental abruption is premature separation of the normally implanted placenta. Features: painful antepartum haemorrhage (bright red or dark blood), uterine rigidity/tenderness (woody hard uterus in severe abruption), uterine hypertonicity (constant pain without relaxation), fetal distress or intrauterine death, and maternal shock disproportionate to visible blood loss (concealed abruption). Ultrasound may be normal — diagnosis is clinical. Complications: DIC, acute renal failure (ATN), PPH, Sheehan syndrome (pituitary necrosis from prolonged hypotension)."]','A','Risk factors: hypertension/pre-eclampsia, smoking, cocaine use, trauma, previous abruption, polyhydramnios, multiparity, PPROM, and thrombophilia. Management: resuscitation, delivery (caesarean if fetal distress or severe abruption; vaginal if mild and fetal wellbeing maintained). Kleihauer test if Rh negative.','universal',true,'{year1,year2,year3,year4,year5,year6,practitioner}','Harrison''s Principles of Internal Medicine 20th Ed');
INSERT INTO questions (professions, course, topic, category, subtopic, difficulty, question_type, question_text, options, correct_answer, explanation, region, high_yield, year_level, source_reference) VALUES
('{"medicine"}','Medicine','Reproductive System & OB-GYN','Clinicals','Obstetric Emergencies','medium','flashcard','What is placenta praevia and how is it managed?','["Placenta praevia is abnormal implantation of the placenta in the lower uterine segment, partially or completely covering the internal os. Classification: minor (placenta in lower segment but not reaching os or partially covering it) and major (completely covering internal os). Presentation: painless antepartum haemorrhage, often at 28–32 weeks. Diagnosis by TVUS. Management: hospitalisation if bleeding, avoid vaginal examination and intercourse, corticosteroids if <34 weeks, caesarean section at 36–37 weeks (major praevia) or as needed. Blood transfusion as required."]','A','Placenta praevia occurs in ~0.5% of pregnancies; risk factors include previous CS, uterine surgery, multiparity, and advanced maternal age. Combined with previous CS scar, it can cause placenta accreta spectrum (accreta, increta, percreta). Blood banking and consultant-led care are essential.','universal',true,'{year1,year2,year3,year4,year5,year6,practitioner}','Harrison''s Principles of Internal Medicine 20th Ed');
INSERT INTO questions (professions, course, topic, category, subtopic, difficulty, question_type, question_text, options, correct_answer, explanation, region, high_yield, year_level, source_reference) VALUES
('{"medicine"}','Medicine','Reproductive System & OB-GYN','Clinicals','Obstetric Emergencies','hard','flashcard','What are the risk factors and surgical options for placenta accreta spectrum (PAS)?','["PAS occurs when placental villi abnormally invade the myometrium due to defective decidua basalis. Degrees: accreta (superficial invasion — 75%), increta (into myometrium — 18%), percreta (through serosa/bladder — 7%). KEY risk factor: previous caesarean section + placenta praevia (risk rises from 3% with 1 CS to 67% with ≥5 CS). Other risk factors: previous uterine surgery, Asherman syndrome, submucous fibroids. Diagnosis: ultrasound (lacunae, loss of retroplacental clear space) or MRI. Management: planned caesarean hysterectomy at 34–35 weeks in a specialist centre with cell salvage and multidisciplinary team."]','A','Conservative management (leaving placenta in situ) is controversial but may be attempted to preserve fertility in selected cases. Balloon occlusion catheters of iliac arteries can be placed pre-operatively to reduce blood loss. Intraoperative mortality from percreta with bladder involvement is significant; urology involvement is required.','universal',true,'{year1,year2,year3,year4,year5,year6,practitioner}','Harrison''s Principles of Internal Medicine 20th Ed');
INSERT INTO questions (professions, course, topic, category, subtopic, difficulty, question_type, question_text, options, correct_answer, explanation, region, high_yield, year_level, source_reference) VALUES
('{"medicine"}','Medicine','Reproductive System & OB-GYN','Clinicals','Obstetric Emergencies','medium','flashcard','What is umbilical cord prolapse and what is its immediate management?','["Cord prolapse: umbilical cord descends through the cervix ahead of or alongside the presenting part after membrane rupture, causing mechanical cord compression by the presenting part and acute fetal hypoxia. Predisposing factors: unstable lie, polyhydramnios, preterm labour, multiple pregnancy, low-lying placenta, artificial rupture of membranes with high presenting part. Immediate management: (1) Do NOT push cord back. (2) Manually elevate presenting part per vaginam to relieve compression. (3) Knee-chest/Trendelenburg position. (4) Keep cord warm and moist. (5) Emergency caesarean section. (6) Bladder filling (500 mL saline) may also elevate presenting part."]','A','If fully dilated and delivery is imminent, instrumental vaginal delivery (forceps/ventouse) may be faster than caesarean. Perinatal mortality ranges from 5–10% if managed in hospital but up to 44% if occurring in community setting. Call-to-delivery time should be <30 minutes.','universal',true,'{year1,year2,year3,year4,year5,year6,practitioner}','Harrison''s Principles of Internal Medicine 20th Ed');
INSERT INTO questions (professions, course, topic, category, subtopic, difficulty, question_type, question_text, options, correct_answer, explanation, region, high_yield, year_level, source_reference) VALUES
('{"medicine"}','Medicine','Reproductive System & OB-GYN','Clinicals','Obstetric Emergencies','hard','flashcard','What are the uterotonic agents used in PPH management and their doses?','["(1) Oxytocin: 10 IU IM (active management); 5 IU slow IV for treatment; 40 IU in 500 mL saline infusion over 4 hours. (2) Ergometrine: 0.5 mg IM or slow IV; contraindicated in hypertension, eclampsia, vascular disease. (3) Syntometrine: oxytocin 5 IU + ergometrine 0.5 mg IM combined. (4) Carboprost (15-methyl PGF2α): 250 mcg IM every 15–90 minutes, max 8 doses; contraindicated in asthma. (5) Misoprostol: 800–1000 mcg rectally/sublingually/orally (used when injectables unavailable or as adjunct). (6) Tranexamic acid: 1 g IV within 3 hours of delivery; repeat once if bleeding continues."]','A','The WOMAN trial (2017) showed tranexamic acid reduces PPH mortality by 19% when given within 3 hours. Carboprost is most potent but contraindicated in asthma (bronchoconstriction). Oxytocin is degraded quickly; ergometrine provides sustained contraction. Dinoprostone (PGE2) can also be used intramyometrially.','universal',true,'{year1,year2,year3,year4,year5,year6,practitioner}','Harrison''s Principles of Internal Medicine 20th Ed');
INSERT INTO questions (professions, course, topic, category, subtopic, difficulty, question_type, question_text, options, correct_answer, explanation, region, high_yield, year_level, source_reference) VALUES
('{"medicine"}','Medicine','Reproductive System & OB-GYN','Clinicals','Obstetric Emergencies','medium','flashcard','What are the features of uterine rupture and how is it managed?','["Clinical features: sudden severe abdominal pain (may ease after rupture — false reassurance), loss of uterine contour/scar pain, fetal presenting part rising out of pelvis on abdominal palpation, haemodynamic shock, cessation of uterine contractions, fetal distress or absence of fetal heart, haematuria if bladder involved. Risk factors: previous CS scar (especially classical), oxytocin use in scarred uterus, obstructed labour, grand multiparity, uterine anomaly. Management: immediate laparotomy, resuscitation, delivery of fetus and placenta, uterine repair (if feasible) or hysterectomy."]','A','Scar rupture vs dehiscence: rupture = full thickness tear with extrusion of fetus/placenta into peritoneal cavity; dehiscence = scar thinning without complete breach of peritoneum. Dehiscence may be asymptomatic and found incidentally at LSCS. Classical (vertical) scar has 4–9% rupture risk; lower segment scar has 0.2–0.7% risk.','universal',true,'{year1,year2,year3,year4,year5,year6,practitioner}','Harrison''s Principles of Internal Medicine 20th Ed');
INSERT INTO questions (professions, course, topic, category, subtopic, difficulty, question_type, question_text, options, correct_answer, explanation, region, high_yield, year_level, source_reference) VALUES
('{"medicine"}','Medicine','Reproductive System & OB-GYN','Clinicals','Preterm Labour & PPROM','easy','flashcard','What antenatal corticosteroid regimen is given for fetal lung maturation in preterm labour?','["Betamethasone 12 mg IM two doses 24 hours apart (preferred) OR dexamethasone 6 mg IM four doses 12 hours apart. Given between 24+0 and 34+6 weeks for all women at risk of preterm delivery within 7 days. Benefits: reduces neonatal RDS by 40%, IVH by 50%, NEC by 50%, and overall neonatal mortality. A single rescue course may be given if >7 days since original course and <34 weeks."]','A','Corticosteroids work by inducing surfactant synthesis in type II pneumocytes. Effect is maximal 24–48 hours after first dose and lasts 7 days. Multiple courses are NOT recommended routinely (risk of growth restriction and adrenal suppression). Corticosteroids do not prevent preterm labour — they optimise neonatal outcome if preterm birth occurs.','universal',true,'{year1,year2,year3,year4,year5,year6,practitioner}','Harrison''s Principles of Internal Medicine 20th Ed');
INSERT INTO questions (professions, course, topic, category, subtopic, difficulty, question_type, question_text, options, correct_answer, explanation, region, high_yield, year_level, source_reference) VALUES
('{"medicine"}','Medicine','Reproductive System & OB-GYN','Clinicals','Preterm Labour & PPROM','medium','flashcard','What tocolytic agents are used in preterm labour and what are their side effects?','["(1) Nifedipine (calcium channel blocker): 20 mg loading then 10–20 mg every 4–6 hours. Side effects: flushing, headache, hypotension. (2) Atosiban (oxytocin antagonist): IV infusion; few maternal side effects; licensed in Europe. (3) Indomethacin (COX inhibitor): used <32 weeks; risk of premature ductus arteriosus closure (avoid >32 weeks), oligohydramnios, NEC. (4) Beta-agonists (salbutamol, terbutaline): significant side effects — tachycardia, pulmonary oedema, hypokalaemia; not recommended first-line. Tocolysis goal: delay delivery 48 hours for corticosteroids and transfer to specialist centre."]','A','No tocolytic agent prevents preterm birth long-term or improves perinatal outcomes beyond the 48-hour window. Tocolysis is contraindicated in chorioamnionitis, placental abruption, severe pre-eclampsia, fetal compromise, and lethal fetal anomaly.','universal',true,'{year1,year2,year3,year4,year5,year6,practitioner}','Harrison''s Principles of Internal Medicine 20th Ed');
INSERT INTO questions (professions, course, topic, category, subtopic, difficulty, question_type, question_text, options, correct_answer, explanation, region, high_yield, year_level, source_reference) VALUES
('{"medicine"}','Medicine','Reproductive System & OB-GYN','Clinicals','Preterm Labour & PPROM','medium','flashcard','What is the management of PPROM at 28 weeks gestation?','["Management of PPROM 28 weeks: (1) Admission and monitoring for infection (temperature, pulse, WBC, CRP, CTG). (2) Corticosteroids (betamethasone 12 mg IM × 2). (3) MgSO4 for neuroprotection if delivery anticipated before 32 weeks. (4) Prophylactic antibiotics: erythromycin 250 mg QDS for 10 days (ORACLE trial — reduces neonatal morbidity; avoid co-amoxiclav/Augmentin — associated with neonatal NEC). (5) Expectant management until 34 weeks if no infection, then delivery. (6) Immediate delivery if chorioamnionitis, placental abruption, or fetal distress."]','A','ORACLE trial (2001): erythromycin prolonged pregnancy, reduced neonatal infection; co-amoxiclav increased NEC. At 34 weeks, delivery is recommended as risk of chorioamnionitis exceeds risk of prematurity. Swab for Group B Streptococcus. Avoid digital vaginal examination (increases infection risk).','universal',true,'{year1,year2,year3,year4,year5,year6,practitioner}','Harrison''s Principles of Internal Medicine 20th Ed');
INSERT INTO questions (professions, course, topic, category, subtopic, difficulty, question_type, question_text, options, correct_answer, explanation, region, high_yield, year_level, source_reference) VALUES
('{"medicine"}','Medicine','Reproductive System & OB-GYN','Clinicals','Preterm Labour & PPROM','hard','flashcard','What is the role of vaginal progesterone in preventing preterm birth?','["Vaginal progesterone (90–200 mg/day micronised progesterone vaginal pessary from 16–24 weeks to 36 weeks) is recommended for asymptomatic women with a singleton pregnancy and short cervical length (<25 mm on TVUS at 18–24 weeks). It reduces the risk of preterm birth before 34 weeks by ~45% and is associated with improved neonatal outcomes. Mechanism: anti-inflammatory, inhibits cervical ripening and myometrial contractility. 17-OHPC (17-hydroxyprogesterone caproate) reduces recurrence in women with prior preterm birth (controversial — PROLONG trial negative)."]','A','Vaginal progesterone is NOT recommended for multiple pregnancies with short cervix (OPPTIMUM and PROGRESS trials showed no benefit). Cervical cerclage may be offered instead for women with prior preterm birth plus short cervix in singleton pregnancies. Combined progesterone + cerclage may be considered in high-risk cases.','universal',true,'{year1,year2,year3,year4,year5,year6,practitioner}','Harrison''s Principles of Internal Medicine 20th Ed');
INSERT INTO questions (professions, course, topic, category, subtopic, difficulty, question_type, question_text, options, correct_answer, explanation, region, high_yield, year_level, source_reference) VALUES
('{"medicine"}','Medicine','Reproductive System & OB-GYN','Clinicals','Preterm Labour & PPROM','easy','flashcard','What are the diagnostic features of clinical chorioamnionitis?','["Clinical chorioamnionitis (intra-amniotic infection): Maternal fever ≥38°C (mandatory criterion) PLUS two or more of: maternal tachycardia >100 bpm, fetal tachycardia >160 bpm, uterine tenderness, foul-smelling or purulent amniotic fluid, elevated maternal WBC >15,000/mm³. Subclinical chorioamnionitis may be asymptomatic with only elevated CRP/WBC. Common organisms: Group B Streptococcus, E. coli, anaerobes, Ureaplasma."]','A','Management: immediate delivery (regardless of gestation) and broad-spectrum IV antibiotics (ampicillin + gentamicin ± metronidazole). Continue antibiotics postpartum until afebrile for 24 hours. Chorioamnionitis is a major cause of preterm labour, maternal sepsis, and neonatal sepsis/meningitis.','universal',true,'{year1,year2,year3,year4,year5,year6,practitioner}','Harrison''s Principles of Internal Medicine 20th Ed');
INSERT INTO questions (professions, course, topic, category, subtopic, difficulty, question_type, question_text, options, correct_answer, explanation, region, high_yield, year_level, source_reference) VALUES
('{"medicine"}','Medicine','Reproductive System & OB-GYN','Clinicals','Preterm Labour & PPROM','medium','flashcard','What neonatal complications occur following extreme preterm birth (<28 weeks)?','["Respiratory: respiratory distress syndrome (RDS — surfactant deficiency), apnoea of prematurity, bronchopulmonary dysplasia (BPD — chronic lung disease). Neurological: intraventricular haemorrhage (IVH — periventricular leukomalacia, cerebral palsy). GI: necrotising enterocolitis (NEC). Metabolic: hypothermia, hypoglycaemia, hypocalcaemia. Infectious: neonatal sepsis. Ophthalmological: retinopathy of prematurity (ROP). Long-term: neurodevelopmental delay, learning difficulties, hearing loss, behavioural problems."]','A','Surfactant replacement therapy (beractant, poractant alfa) given within 2 hours of birth significantly reduces RDS severity. Non-invasive respiratory support (CPAP) is preferred over intubation where possible (COIN trial). Caffeine citrate reduces apnoea and improves neurodevelopmental outcomes.','universal',true,'{year1,year2,year3,year4,year5,year6,practitioner}','Harrison''s Principles of Internal Medicine 20th Ed');
INSERT INTO questions (professions, course, topic, category, subtopic, difficulty, question_type, question_text, options, correct_answer, explanation, region, high_yield, year_level, source_reference) VALUES
('{"medicine"}','Medicine','Reproductive System & OB-GYN','Clinicals','Preterm Labour & PPROM','hard','flashcard','How is the diagnosis of preterm labour confirmed?','["Clinical criteria: regular uterine contractions (≥4 in 20 minutes) + cervical change (dilation ≥2 cm or effacement ≥80%). Adjunctive tests to predict preterm birth: (1) Fetal fibronectin (fFN) swab from posterior vaginal fornix: a negative result at 22–34 weeks has NPV >99% for delivery within 2 weeks — reassures clinician NOT to intervene. (2) Cervical length by TVUS: <15 mm is associated with high preterm delivery risk; ≥30 mm is very reassuring. Combined fFN + cervical length gives highest predictive value."]','A','A positive fFN test alone has poor PPV (~20–30%) but is useful combined with short cervix. In clinical practice, negative fFN is the most useful finding — it avoids unnecessary tocolysis, corticosteroids, and hospitalisation. Amniocentesis to detect intra-amniotic infection may be done in equivocal cases.','universal',false,'{year1,year2,year3,year4,year5,year6,practitioner}','Harrison''s Principles of Internal Medicine 20th Ed');
INSERT INTO questions (professions, course, topic, category, subtopic, difficulty, question_type, question_text, options, correct_answer, explanation, region, high_yield, year_level, source_reference) VALUES
('{"medicine"}','Medicine','Reproductive System & OB-GYN','Clinicals','Preterm Labour & PPROM','medium','flashcard','What is cervical cerclage and when is it indicated?','["Cervical cerclage is a surgical procedure placing a suture around the cervix to maintain cervical length and competence. Indications: (1) History-indicated (elective): women with ≥3 second-trimester losses or preterm births due to cervical factor — placed at 12–14 weeks. (2) Ultrasound-indicated: singleton pregnancy with cervical length <25 mm before 24 weeks AND prior preterm birth. (3) Rescue cerclage: dilated cervix with membranes bulging in the second trimester — higher risk. Removal at 36–37 weeks. Complications: membrane rupture, chorioamnionitis, bleeding."]','A','Cerclage is not indicated for multiple pregnancies (MRC trials showed no benefit). The McDonald and Shirodkar techniques are most common. Cervical pessary (Arabin pessary) is a non-surgical alternative for short cervix with similar efficacy in some trials. Contraindications: chorioamnionitis, active bleeding, labour.','universal',true,'{year1,year2,year3,year4,year5,year6,practitioner}','Harrison''s Principles of Internal Medicine 20th Ed');
INSERT INTO questions (professions, course, topic, category, subtopic, difficulty, question_type, question_text, options, correct_answer, explanation, region, high_yield, year_level, source_reference) VALUES
('{"medicine"}','Medicine','Reproductive System & OB-GYN','Clinicals','Preterm Labour & PPROM','easy','flashcard','At what gestational age and dose is magnesium sulphate given for fetal neuroprotection?','["MgSO4 is given for neuroprotection to women at risk of imminent preterm birth at <32 weeks (some protocols <34 weeks). Standard protocol: loading dose 4 g IV over 20–30 minutes, then maintenance 1 g/hour until delivery or for 24 hours maximum. If delivery does not occur and risk recurs later, the course can be repeated. MgSO4 reduces risk of cerebral palsy by ~32% and significant motor dysfunction by ~40% (Cochrane 2009)."]','A','Mechanism of neuroprotection: MgSO4 acts as NMDA receptor antagonist reducing excitotoxic glutamate injury, and as a vasodilator improving cerebral blood flow. Side effects: flushing, nausea. Monitor: respiratory rate, urine output, reflexes. Antidote: calcium gluconate 1 g IV.','universal',true,'{year1,year2,year3,year4,year5,year6,practitioner}','Harrison''s Principles of Internal Medicine 20th Ed');
INSERT INTO questions (professions, course, topic, category, subtopic, difficulty, question_type, question_text, options, correct_answer, explanation, region, high_yield, year_level, source_reference) VALUES
('{"medicine"}','Medicine','Reproductive System & OB-GYN','Clinicals','Preterm Labour & PPROM','hard','flashcard','What are the risk factors for spontaneous preterm birth?','["Prior spontaneous preterm birth (strongest risk factor, 2–6-fold increased risk), multiple pregnancy (highest risk group — 50% of twins deliver preterm), cervical surgery (LLETZ — dose-dependent risk), uterine anomaly (bicornuate uterus), cervical incompetence, intrauterine infection, polyhydramnios, low socioeconomic status, smoking, extremes of BMI (<18.5 or >30), African ethnicity, interval <18 months between pregnancies, ART-conceived pregnancy, antepartum haemorrhage."]','A','Recurrence risk after one spontaneous preterm birth is ~15–30%; after two, ~30–50%. Progesterone and cervical cerclage are interventions with proven benefit in high-risk women. Inter-pregnancy interval optimisation and smoking cessation are preventable risk factors. Bacterial vaginosis treatment in asymptomatic women does not reduce PTB.','universal',true,'{year1,year2,year3,year4,year5,year6,practitioner}','Harrison''s Principles of Internal Medicine 20th Ed');
INSERT INTO questions (professions, course, topic, category, subtopic, difficulty, question_type, question_text, options, correct_answer, explanation, region, high_yield, year_level, source_reference) VALUES
('{"medicine"}','Medicine','Reproductive System & OB-GYN','Clinicals','Ectopic Pregnancy','easy','flashcard','What are the risk factors for ectopic pregnancy?','["Previous PID or STI (Chlamydia trachomatis — most important risk factor, 6–10-fold increase), previous ectopic pregnancy (10-fold increase; recurrence risk 10–15%), previous tubal surgery (salpingotomy, sterilisation), intrauterine device (relative risk increased — 6-fold increase if pregnancy occurs with IUD in situ), assisted reproductive technologies (IVF — 3% ectopic risk), endometriosis, previous appendicitis/peritonitis with pelvic adhesions, smoking, and advanced maternal age."]','A','15–20% of first trimester pregnancies in women with prior ectopic are ectopic. All women with positive pregnancy test and risk factors should have early TVUS at 6 weeks to confirm intrauterine location. After one ectopic, the risk of a second ectopic is 10–15%; after two, it rises to ~30%.','universal',true,'{year1,year2,year3,year4,year5,year6,practitioner}','Harrison''s Principles of Internal Medicine 20th Ed');
INSERT INTO questions (professions, course, topic, category, subtopic, difficulty, question_type, question_text, options, correct_answer, explanation, region, high_yield, year_level, source_reference) VALUES
('{"medicine"}','Medicine','Reproductive System & OB-GYN','Clinicals','Ectopic Pregnancy','medium','flashcard','What are the criteria for medical management of ectopic pregnancy with methotrexate?','["Criteria for methotrexate (single-dose 50 mg/m²  IM): (1) Haemodynamically stable. (2) Ectopic mass ≤3.5 cm (some protocols ≤4 cm). (3) No fetal cardiac activity on TVUS. (4) Serum hCG <5,000 IU/L (optimal <1,500 IU/L for best success). (5) No contraindications: liver disease, renal impairment, thrombocytopenia, immunodeficiency, breastfeeding. (6) Patient willing and able to comply with follow-up. Follow-up: hCG on days 4 and 7; ≥15% fall confirms success. If fails: second dose or surgery."]','A','Methotrexate inhibits dihydrofolate reductase, preventing DNA synthesis in rapidly dividing trophoblast cells. Side effects: nausea, stomatitis, abdominal pain (separation pain days 3–7), transient LFT elevation. Avoid: NSAIDS (reduce renal clearance), folic acid supplements, alcohol, and sun exposure during treatment. Advise contraception for 3 months after treatment.','universal',true,'{year1,year2,year3,year4,year5,year6,practitioner}','Harrison''s Principles of Internal Medicine 20th Ed');
INSERT INTO questions (professions, course, topic, category, subtopic, difficulty, question_type, question_text, options, correct_answer, explanation, region, high_yield, year_level, source_reference) VALUES
('{"medicine"}','Medicine','Reproductive System & OB-GYN','Clinicals','Ectopic Pregnancy','medium','flashcard','What is the hCG discriminatory zone and what does it mean clinically?','["The discriminatory zone is the serum beta-hCG level above which a normal intrauterine pregnancy should be detectable by TVUS: typically 1,500–2,000 IU/L for transvaginal ultrasound (some use 6,500 IU/L for transabdominal). If hCG is above the discriminatory zone and no IUP is seen on TVUS, the diagnosis is a pregnancy of unknown location (PUL) — likely ectopic or abnormal IUP. If hCG is below the zone, wait and repeat hCG in 48 hours. hCG should rise by ≥66% in 48 hours for a viable IUP."]','A','A hCG that rises less than 66% in 48 hours suggests abnormal pregnancy (ectopic or non-viable IUP); a rise >66% suggests viable IUP. A falling hCG may indicate miscarriage or resolving ectopic. Inconclusive cases require diagnostic laparoscopy or further monitoring. Heterotopic pregnancy (simultaneous IUP + ectopic) can occur, especially with IVF.','universal',true,'{year1,year2,year3,year4,year5,year6,practitioner}','Harrison''s Principles of Internal Medicine 20th Ed');
INSERT INTO questions (professions, course, topic, category, subtopic, difficulty, question_type, question_text, options, correct_answer, explanation, region, high_yield, year_level, source_reference) VALUES
('{"medicine"}','Medicine','Reproductive System & OB-GYN','Clinicals','Ectopic Pregnancy','hard','flashcard','What is an interstitial (cornual) ectopic pregnancy and why is it dangerous?','["An interstitial (cornual) ectopic pregnancy implants in the intramural portion of the fallopian tube within the uterine wall. It accounts for 2–4% of all ectopics. Dangers: (1) It is surrounded by myometrium so it can grow larger before rupturing (8–12 weeks vs 6–8 weeks for other tube). (2) When it ruptures, it causes catastrophic haemorrhage — the cornual region has a rich blood supply from uterine and ovarian arteries. Diagnosis: TVUS shows empty uterine cavity, gestational sac lateral to uterine horn, thin myometrial mantle <5 mm. Treatment: systemic or local methotrexate, or cornuostomy/cornual resection."]','A','Ultrasound diagnosis can be difficult — the interstitial line sign (echogenic line extending from uterine cavity into the gestational sac) is a specific TVUS feature. 3D ultrasound and MRI can help. Hysterectomy may be required for uncontrolled haemorrhage. Recurrent ectopic risk is not increased after cornual resection without salpingectomy.','universal',false,'{year1,year2,year3,year4,year5,year6,practitioner}','Harrison''s Principles of Internal Medicine 20th Ed');
INSERT INTO questions (professions, course, topic, category, subtopic, difficulty, question_type, question_text, options, correct_answer, explanation, region, high_yield, year_level, source_reference) VALUES
('{"medicine"}','Medicine','Reproductive System & OB-GYN','Clinicals','Ectopic Pregnancy','easy','flashcard','What are the symptoms and signs of a ruptured ectopic pregnancy?','["Symptoms: sudden onset severe unilateral lower abdominal pain, shoulder tip pain (diaphragmatic irritation from haemoperitoneum), nausea, vomiting, dizziness, and collapse. History: amenorrhoea 6–8 weeks, positive pregnancy test, possible vaginal bleeding (though bleeding may be minimal). Signs: haemodynamic shock (tachycardia, hypotension, pale, sweaty), peritonism (guarding, rebound tenderness), cervical motion tenderness and adnexal tenderness on bimanual examination, mass in pouch of Douglas."]','A','A ruptured ectopic is a surgical emergency with maternal mortality if not promptly treated. The Cullen sign (periumbilical bruising from haemoperitoneum) is a rare late sign. Always suspect ectopic in any woman of reproductive age with shock + positive pregnancy test. Diagnosis confirmed by TVUS (free fluid) or diagnostic laparoscopy.','universal',true,'{year1,year2,year3,year4,year5,year6,practitioner}','Harrison''s Principles of Internal Medicine 20th Ed');
INSERT INTO questions (professions, course, topic, category, subtopic, difficulty, question_type, question_text, options, correct_answer, explanation, region, high_yield, year_level, source_reference) VALUES
('{"medicine"}','Medicine','Reproductive System & OB-GYN','Clinicals','Ectopic Pregnancy','medium','flashcard','Compare salpingotomy vs salpingectomy for tubal ectopic pregnancy.','["Salpingotomy (tube-conserving): incision over ectopic, removal of pregnancy, tube left in situ. Advantage: preserves tube for future fertility. Disadvantage: persistent trophoblast risk 5–10% (requires hCG monitoring), higher risk of subsequent ipsilateral ectopic. Recommended when contralateral tube is damaged or absent. Salpingectomy (tube removal): complete removal of affected tube. Advantage: no persistent trophoblast risk, avoids ipsilateral recurrence. Disadvantage: reduces total tubal length. RCOG recommends salpingectomy when contralateral tube is healthy. Subsequent IUP rates are similar between the two."]','A','The ESEP trial (2014) found similar intrauterine pregnancy rates at 36 months for salpingotomy vs salpingectomy, but lower ectopic recurrence with salpingectomy (8% vs 18%). Both procedures can be performed laparoscopically (preferred over laparotomy) when the patient is haemodynamically stable.','universal',true,'{year1,year2,year3,year4,year5,year6,practitioner}','Harrison''s Principles of Internal Medicine 20th Ed');
INSERT INTO questions (professions, course, topic, category, subtopic, difficulty, question_type, question_text, options, correct_answer, explanation, region, high_yield, year_level, source_reference) VALUES
('{"medicine"}','Medicine','Reproductive System & OB-GYN','Clinicals','Ectopic Pregnancy','medium','flashcard','What is a heterotopic pregnancy?','["A heterotopic pregnancy is the simultaneous occurrence of an intrauterine pregnancy AND an ectopic pregnancy. Natural incidence is approximately 1 in 30,000 pregnancies, but rises to 1 in 100–500 with assisted reproductive technologies (IVF/ICSI) due to multiple embryo transfer. Clinical challenge: the intrauterine pregnancy may be viable and hCG rises normally, so ectopic may be missed. Treatment: surgical removal of the ectopic (laparoscopy) with careful preservation of the intrauterine pregnancy. Methotrexate is contraindicated as it would harm the intrauterine embryo."]','A','Always perform careful TVUS examination of the adnexa even when an IUP is confirmed in women who have undergone ART. Heterotopic pregnancy is a diagnostic trap that can lead to delayed rupture and maternal morbidity.','universal',false,'{year1,year2,year3,year4,year5,year6,practitioner}','Harrison''s Principles of Internal Medicine 20th Ed');
INSERT INTO questions (professions, course, topic, category, subtopic, difficulty, question_type, question_text, options, correct_answer, explanation, region, high_yield, year_level, source_reference) VALUES
('{"medicine"}','Medicine','Reproductive System & OB-GYN','Clinicals','Ectopic Pregnancy','hard','flashcard','How is expectant management used for ectopic pregnancy?','["Expectant management can be considered in highly selected, asymptomatic women with small, unruptured ectopic pregnancies where: hCG is low and falling spontaneously (initial hCG <1,000–1,500 IU/L and declining ≥15% over 48 hours), adnexal mass ≤3 cm, no fetal cardiac activity, no significant free fluid, and the patient is haemodynamically stable with reliable access to emergency care. Success rate ~48–70% when criteria met. Serial hCG monitoring every 48 hours until negative. If hCG rises or fails to fall, medical or surgical management is required."]','A','Expectant management avoids unnecessary intervention and preserves fertility. However, failure rates are significant and patients must be closely monitored. Patient selection is crucial — women must understand the risk of rupture and have 24-hour access to emergency care. Most guidelines (RCOG, ACOG) recommend individualising the approach.','universal',false,'{year1,year2,year3,year4,year5,year6,practitioner}','Harrison''s Principles of Internal Medicine 20th Ed');
INSERT INTO questions (professions, course, topic, category, subtopic, difficulty, question_type, question_text, options, correct_answer, explanation, region, high_yield, year_level, source_reference) VALUES
('{"medicine"}','Medicine','Reproductive System & OB-GYN','Clinicals','Ectopic Pregnancy','medium','flashcard','What is a caesarean scar ectopic pregnancy (CSP)?','["CSP is implantation of a pregnancy within the fibrous tissue of a previous caesarean section scar in the anterior lower uterine segment. It is the rarest but most dangerous type of ectopic. Risk increases with each previous CS. TVUS features: gestational sac in lower anterior uterine wall/CS scar, empty uterine cavity and cervical canal, absent or thin (≤5 mm) myometrium between sac and bladder. Risk: massive haemorrhage, uterine rupture, bladder involvement. Treatment options: systemic or local methotrexate injection (early cases), high-intensity focused ultrasound (HIFU), uterine artery embolisation, surgical excision by hysteroscopy or laparotomy."]','A','CSP must be diagnosed early (before 8 weeks) to allow conservative management. If allowed to progress, it can become a placenta praevia accreta at term with risk of catastrophic haemorrhage requiring hysterectomy. Rising CS rates worldwide are increasing CSP incidence. 3D TVUS and colour Doppler are helpful in diagnosis.','universal',false,'{year1,year2,year3,year4,year5,year6,practitioner}','Harrison''s Principles of Internal Medicine 20th Ed');
INSERT INTO questions (professions, course, topic, category, subtopic, difficulty, question_type, question_text, options, correct_answer, explanation, region, high_yield, year_level, source_reference) VALUES
('{"medicine"}','Medicine','Reproductive System & OB-GYN','Clinicals','Ectopic Pregnancy','easy','flashcard','Which blood test must be checked in all Rh-negative women with ectopic pregnancy?','["Rhesus (Rh) blood group must be checked in all women with ectopic pregnancy. Rh-negative women who are non-sensitised must receive anti-D immunoglobulin 250 IU IM to prevent Rh alloimmunisation. This applies regardless of: gestational age (even <12 weeks), management type (surgical, medical, or expectant), and whether significant bleeding occurred or not. Anti-D should be given within 72 hours of the sensitising event."]','A','Failure to administer anti-D can cause Rh sensitisation, leading to haemolytic disease of the fetus and newborn in future pregnancies (hydrops fetalis, stillbirth). This is particularly important in resource-limited settings where women may present with their first ectopic in a state of shock — anti-D must not be overlooked.','universal',true,'{year1,year2,year3,year4,year5,year6,practitioner}','Harrison''s Principles of Internal Medicine 20th Ed');
INSERT INTO questions (professions, course, topic, category, subtopic, difficulty, question_type, question_text, options, correct_answer, explanation, region, high_yield, year_level, source_reference) VALUES
('{"medicine"}','Medicine','Reproductive System & OB-GYN','Clinicals','Gestational Diabetes','easy','flashcard','What are the risk factors for gestational diabetes mellitus (GDM)?','["BMI ≥30 kg/m², previous GDM, previous macrosomic baby (birthweight >4.5 kg), first-degree family history of type 2 diabetes, South Asian/Black African/African-Caribbean or Middle Eastern ethnicity, maternal age >35, polycystic ovary syndrome (PCOS), multiple pregnancy, and previous unexplained stillbirth. In Ghana/Africa, the 75 g OGTT at 24–28 weeks is the standard diagnostic test in at-risk women."]','A','GDM complicates 3–15% of pregnancies (higher in high-risk populations). Insulin resistance increases physiologically in the second and third trimesters due to placental hormones (hPL, progesterone, cortisol, prolactin). Women who cannot compensate with increased insulin secretion develop GDM.','universal',true,'{year1,year2,year3,year4,year5,year6,practitioner}','Harrison''s Principles of Internal Medicine 20th Ed');
INSERT INTO questions (professions, course, topic, category, subtopic, difficulty, question_type, question_text, options, correct_answer, explanation, region, high_yield, year_level, source_reference) VALUES
('{"medicine"}','Medicine','Reproductive System & OB-GYN','Clinicals','Gestational Diabetes','medium','flashcard','What maternal and fetal complications are associated with GDM?','["Maternal: pre-eclampsia (2-fold increased risk), caesarean section, operative vaginal delivery, perineal trauma from macrosomia, future type 2 diabetes (35–60% risk within 10 years), recurrent GDM (50–75%). Fetal/neonatal: macrosomia (EFW >4 kg), shoulder dystocia, birth trauma (fractures, brachial plexus injury), neonatal hypoglycaemia (hyperinsulinism), polycythaemia, respiratory distress, jaundice, stillbirth (with poor glycaemic control), and long-term obesity/T2DM risk in offspring."]','A','The Pedersen hypothesis explains neonatal hypoglycaemia: maternal hyperglycaemia → fetal hyperglycaemia → fetal pancreatic beta-cell hyperplasia → fetal hyperinsulinism → neonatal hypoglycaemia after cord clamping. GDM-related stillbirth risk is mainly in the 38th–40th week in poorly controlled cases.','universal',true,'{year1,year2,year3,year4,year5,year6,practitioner}','Harrison''s Principles of Internal Medicine 20th Ed');
INSERT INTO questions (professions, course, topic, category, subtopic, difficulty, question_type, question_text, options, correct_answer, explanation, region, high_yield, year_level, source_reference) VALUES
('{"medicine"}','Medicine','Reproductive System & OB-GYN','Clinicals','Gestational Diabetes','medium','flashcard','How is insulin therapy initiated in GDM when targets are not met with diet?','["Insulin is initiated when blood glucose targets are not achieved with diet and lifestyle (and metformin if used). Starting regimen depends on pattern of hyperglycaemia: (1) Fasting hyperglycaemia only: long-acting insulin (insulin detemir or glargine) at bedtime. (2) Post-meal hyperglycaemia: short-acting insulin (insulin aspart or lispro) before meals. (3) Both: twice-daily pre-mixed insulin or basal-bolus regimen. Targets: fasting <5.3 mmol/L, 1-hour postprandial <7.8 mmol/L. HbA1c is not used for monitoring in GDM; SMBG is used."]','A','Insulin does not cross the placenta. Insulin requirements typically increase by 50–100% by the third trimester due to increasing insulin resistance. After delivery, insulin requirements drop dramatically; GDM mothers are often off insulin within hours of delivery. Postpartum OGTT at 6–13 weeks screens for persistent T2DM.','universal',true,'{year1,year2,year3,year4,year5,year6,practitioner}','Harrison''s Principles of Internal Medicine 20th Ed');
INSERT INTO questions (professions, course, topic, category, subtopic, difficulty, question_type, question_text, options, correct_answer, explanation, region, high_yield, year_level, source_reference) VALUES
('{"medicine"}','Medicine','Reproductive System & OB-GYN','Clinicals','Gestational Diabetes','hard','flashcard','What is the White classification of diabetes in pregnancy?','["The White classification (1949, modified) categorises diabetes in pregnancy by age of onset, duration, and complications: Class A1: GDM controlled by diet; A2: GDM requiring insulin. Class B: onset ≥20 years, duration <10 years, no vascular disease. Class C: onset 10–19 years or duration 10–19 years. Class D: onset <10 years or duration >20 years or background retinopathy. Class F: diabetic nephropathy. Class R: proliferative retinopathy. Class H: ischaemic heart disease. Class T: prior renal transplant. Higher classes = greater maternal and fetal risk."]','A','Although now largely superseded by modern risk stratification, the White classification is still referenced in obstetric literature and is a common exam question. Pre-conception HbA1c optimisation, folic acid 5 mg/day, retinal and renal screening, and medication review (stop ACEi, statins; switch to insulin if on oral agents) are key pre-conception steps for Class B and above.','universal',false,'{year1,year2,year3,year4,year5,year6,practitioner}','Harrison''s Principles of Internal Medicine 20th Ed');
INSERT INTO questions (professions, course, topic, category, subtopic, difficulty, question_type, question_text, options, correct_answer, explanation, region, high_yield, year_level, source_reference) VALUES
('{"medicine"}','Medicine','Reproductive System & OB-GYN','Clinicals','Gestational Diabetes','easy','flashcard','What postpartum tests are recommended after GDM?','["(1) OGTT (75 g) at 6–13 weeks postpartum: fasting glucose and 2-hour post-load glucose to screen for persistent T2DM or impaired fasting glucose/impaired glucose tolerance. (2) Annual fasting plasma glucose or HbA1c for life if OGTT normal. (3) Weight and lifestyle counselling — weight loss and exercise reduce progression to T2DM by ~60% (DPP trial). (4) Breastfeeding encouraged — reduces maternal and neonatal T2DM risk. Offspring should be monitored for childhood obesity and glucose intolerance."]','A','The 6-week OGTT is the gold standard but often missed; HbA1c alone may miss impaired glucose tolerance. Progression to T2DM is highest in the first 5 years postpartum (15–30% per year in high-risk groups). Metformin 850 mg BD can be considered if lifestyle measures fail in women with impaired glucose regulation postpartum.','universal',true,'{year1,year2,year3,year4,year5,year6,practitioner}','Harrison''s Principles of Internal Medicine 20th Ed');
INSERT INTO questions (professions, course, topic, category, subtopic, difficulty, question_type, question_text, options, correct_answer, explanation, region, high_yield, year_level, source_reference) VALUES
('{"medicine"}','Medicine','Reproductive System & OB-GYN','Clinicals','Gestational Diabetes','medium','flashcard','What ultrasound findings suggest GDM macrosomia and how is macrosomia managed?','["Macrosomia in GDM is suggested by: EFW ≥90th centile or >4 kg, increased abdominal circumference (AC), polyhydramnios (AFI >24 cm or deepest pool >8 cm — due to fetal diuresis from hyperglycaemia). Serial growth scans every 4 weeks from 28–32 weeks are recommended in GDM. Management: optimise glycaemic control (primary measure), discuss mode of delivery. Elective caesarean section is offered if EFW >4.5 kg. For EFW 4.0–4.5 kg: individualised decision based on glycaemic control, patient preference, and obstetric history."]','A','Ultrasound EFW has ±15–20% error at term. The HC:AC ratio in GDM macrosomia is typically reduced (liver glycogen deposition makes AC disproportionately large — asymmetric macrosomia opposite to IUGR pattern). Induction at 38 weeks for EFW >4 kg reduces shoulder dystocia risk without increasing CS rate (ACOG).','universal',false,'{year1,year2,year3,year4,year5,year6,practitioner}','Harrison''s Principles of Internal Medicine 20th Ed');
INSERT INTO questions (professions, course, topic, category, subtopic, difficulty, question_type, question_text, options, correct_answer, explanation, region, high_yield, year_level, source_reference) VALUES
('{"medicine"}','Medicine','Reproductive System & OB-GYN','Clinicals','Gestational Diabetes','medium','flashcard','What intrapartum glucose management is needed for a woman with insulin-treated GDM?','["During labour and delivery: (1) Monitor capillary blood glucose hourly. (2) Target: 4.0–7.0 mmol/L. (3) Withhold insulin once active labour established and oral intake stopped. (4) If glucose >7 mmol/L: start IV insulin sliding scale (insulin and dextrose infusion). (5) Stop metformin when in labour. (6) Avoid prolonged labour (ketosis risk). After delivery: stop insulin immediately — insulin requirements drop to near pre-pregnancy levels. Monitor glucose 1–2-hourly postpartum."]','A','Hyperglycaemia during labour causes neonatal hyperinsulinism and hypoglycaemia. Neonates of GDM mothers should be fed within 30 minutes of birth and blood glucose checked at 2–4 hours. Neonatal glucose <2.6 mmol/L requires IV dextrose. NICU admission is needed for severely macrosomic or hypoglycaemic neonates.','universal',true,'{year1,year2,year3,year4,year5,year6,practitioner}','Harrison''s Principles of Internal Medicine 20th Ed');
INSERT INTO questions (professions, course, topic, category, subtopic, difficulty, question_type, question_text, options, correct_answer, explanation, region, high_yield, year_level, source_reference) VALUES
('{"medicine"}','Medicine','Reproductive System & OB-GYN','Clinicals','Gestational Diabetes','hard','flashcard','What is the pathophysiology of insulin resistance in pregnancy?','["Physiological insulin resistance increases progressively through the second and third trimesters, reaching its peak at 26–28 weeks. Mechanism: placental hormones antagonise insulin action — human placental lactogen (hPL) is the major diabetogen, along with placental growth hormone, progesterone, cortisol, and prolactin. These hormones promote lipolysis (increased FFA), downregulate GLUT4 transporters, and inhibit post-receptor insulin signalling. In normal pregnancy, maternal pancreatic beta-cell mass and insulin secretion increase 200–250% to compensate. In GDM, this compensation fails due to pre-existing beta-cell dysfunction or reduced reserve."]','A','After delivery, placental hormones are rapidly cleared and insulin sensitivity returns to normal within hours to days. This explains why insulin requirements drop dramatically postpartum. The pathophysiology of GDM is essentially the same as T2DM (insulin resistance + beta-cell failure), just unmasked by the physiological stress of pregnancy.','universal',false,'{year1,year2,year3,year4,year5,year6,practitioner}','Harrison''s Principles of Internal Medicine 20th Ed');
INSERT INTO questions (professions, course, topic, category, subtopic, difficulty, question_type, question_text, options, correct_answer, explanation, region, high_yield, year_level, source_reference) VALUES
('{"medicine"}','Medicine','Reproductive System & OB-GYN','Clinicals','Gestational Diabetes','easy','flashcard','What dietary advice is given to women newly diagnosed with GDM?','["Dietary advice for GDM: (1) Eat regular meals and snacks (3 meals + 2–3 snacks). (2) Choose low-glycaemic index carbohydrates (oats, pulses, wholegrain bread, vegetables). (3) Limit refined carbohydrates and sugary drinks. (4) Carbohydrate should constitute 35–45% of total caloric intake (not eliminated). (5) Increase fibre intake. (6) Avoid excessive weight gain. (7) Regular moderate exercise (30 minutes daily — walking, swimming) reduces insulin resistance. Referral to dietitian is essential."]','A','Dietary modification alone achieves glucose targets in ~60–70% of GDM cases. Women should not fast or severely restrict calories as this causes ketonuria (fetal ketone exposure may impair neurodevelopment). Specific dietary advice must be culturally sensitive — especially important in Ghana/West Africa where high-carbohydrate staple foods are common.','universal',true,'{year1,year2,year3,year4,year5,year6,practitioner}','Harrison''s Principles of Internal Medicine 20th Ed');
INSERT INTO questions (professions, course, topic, category, subtopic, difficulty, question_type, question_text, options, correct_answer, explanation, region, high_yield, year_level, source_reference) VALUES
('{"medicine"}','Medicine','Reproductive System & OB-GYN','Clinicals','Gestational Diabetes','medium','flashcard','When is elective delivery offered to women with GDM?','["GDM on diet alone with good control and no complications: offer induction of labour at 40+0 to 40+6 weeks (not before 40 weeks). GDM requiring metformin or insulin OR with macrosomia (EFW >4 kg): offer induction at 38+0 to 38+6 weeks. EFW >4.5 kg: offer CS or induction at 37–38 weeks after senior obstetric counselling. Pre-existing diabetes (T1DM or T2DM): offer induction at 37+0 weeks. Women with pre-existing diabetes and complications (nephropathy, retinopathy, poor control): earlier delivery may be indicated."]','A','Delaying delivery beyond 40 weeks in GDM women significantly increases the risk of stillbirth. ACOG recommends delivery at 39–40 weeks for diet-controlled GDM and 38–39 weeks for insulin-requiring GDM. Induction at 38 weeks does not increase caesarean section rates compared to expectant management.','universal',true,'{year1,year2,year3,year4,year5,year6,practitioner}','Harrison''s Principles of Internal Medicine 20th Ed');
INSERT INTO questions (professions, course, topic, category, subtopic, difficulty, question_type, question_text, options, correct_answer, explanation, region, high_yield, year_level, source_reference) VALUES
('{"medicine"}','Medicine','Reproductive System & OB-GYN','Clinicals','Abnormal Uterine Bleeding','easy','flashcard','What is the PALM-COEIN classification of abnormal uterine bleeding?','["PALM (structural): Polyp, Adenomyosis, Leiomyoma (fibroid — subclassified: SM0-SM2 submucosal, types 1–8 for other), Malignancy and hyperplasia. COEIN (non-structural): Coagulopathy (VWD, platelet disorders, anticoagulants), Ovulatory dysfunction (PCOS, thyroid disease, hyperprolactinaemia), Endometrial (primary endometrial haemostatic defects), Iatrogenic (IUD, anticoagulants, hormone therapy), Not yet classified. Developed by FIGO in 2011 to standardise AUB terminology and replace terms like dysfunctional uterine bleeding."]','A','Key definitions: Heavy menstrual bleeding (HMB) = >80 mL/cycle or impact on quality of life; intermenstrual bleeding (IMB) = between periods; postcoital bleeding (PCB) = after intercourse; postmenopausal bleeding (PMB) = ≥12 months after last period. Acute AUB = severe bleeding requiring urgent intervention. The PALM-COEIN system guides targeted investigation and treatment.','universal',true,'{year1,year2,year3,year4,year5,year6,practitioner}','Harrison''s Principles of Internal Medicine 20th Ed');
INSERT INTO questions (professions, course, topic, category, subtopic, difficulty, question_type, question_text, options, correct_answer, explanation, region, high_yield, year_level, source_reference) VALUES
('{"medicine"}','Medicine','Reproductive System & OB-GYN','Clinicals','Abnormal Uterine Bleeding','medium','flashcard','How are uterine fibroids classified by location and how does this affect symptoms and treatment?','["FIGO fibroid classification: SM (submucosal): 0 = pedunculated intracavitary; 1 = <50% intramural; 2 = ≥50% intramural. Types 3–5: intramural. Type 6: subserosal <50% intramural; Type 7: pedunculated subserosal; Type 8: parasitic/cervical. Submucosal fibroids (SM0–2) cause HMB and infertility — treated by hysteroscopic resection. Intramural fibroids cause HMB and bulk symptoms — treated with UAE, myomectomy, HIFU, or GnRH analogues. Subserosal fibroids cause pressure symptoms — treated with myomectomy. UAE is contraindicated for pedunculated subserosal fibroids."]','A','Uterine fibroids affect ~20–30% of women of reproductive age; more common in Black African women (2–3-fold). Aetiology: oestrogen/progesterone-dependent growth (shrink at menopause). Medical treatment: GnRH analogues (reduce fibroid volume 40–60% over 3–6 months — used preoperatively); ulipristal acetate (selective progesterone receptor modulator — withdrawn in Europe due to hepatotoxicity).','universal',true,'{year1,year2,year3,year4,year5,year6,practitioner}','Harrison''s Principles of Internal Medicine 20th Ed');
INSERT INTO questions (professions, course, topic, category, subtopic, difficulty, question_type, question_text, options, correct_answer, explanation, region, high_yield, year_level, source_reference) VALUES
('{"medicine"}','Medicine','Reproductive System & OB-GYN','Clinicals','Abnormal Uterine Bleeding','medium','flashcard','What investigations are recommended in a woman with heavy menstrual bleeding?','["First-line: full blood count (FBC — assess anaemia), TVUS (structural cause), and if indicated: thyroid function tests (hypothyroidism causes menorrhagia), coagulation screen + VWF antigen/activity (if menorrhagia since menarche or family history of bleeding disorders), and cervical smear if overdue. Second-line: hysteroscopy + endometrial biopsy (if >45, postmenopausal bleeding, persistent IMB, TVUS endometrium >4–5 mm, or failed medical treatment). MRI: for complex pelvic pathology, fibroid mapping pre-UAE/myomectomy."]','A','TVUS is the first-line imaging investigation. Saline infusion sonography (SIS) or HyCoSy improves detection of submucosal fibroids and polyps. Endometrial biopsy has ~90% sensitivity for endometrial cancer (false-negative rate ~10% — hysteroscopy required if high suspicion persists). Pipelle device is the standard outpatient biopsy method.','universal',true,'{year1,year2,year3,year4,year5,year6,practitioner}','Harrison''s Principles of Internal Medicine 20th Ed');
INSERT INTO questions (professions, course, topic, category, subtopic, difficulty, question_type, question_text, options, correct_answer, explanation, region, high_yield, year_level, source_reference) VALUES
('{"medicine"}','Medicine','Reproductive System & OB-GYN','Clinicals','Abnormal Uterine Bleeding','hard','flashcard','What is the management of endometrial hyperplasia?','["Simple hyperplasia without atypia: low cancer risk (<1%). Treat with progestins (LNG-IUS first-line, or oral progestins e.g., norethisterone 10–15 mg/day for 3 months) or observation. Repeat biopsy at 6 months. Complex hyperplasia without atypia: low risk (~3%). Similar treatment. Atypical hyperplasia/endometrial intraepithelial neoplasia (EIN): 30–50% risk of concurrent or subsequent endometrial carcinoma. Treatment: (1) Hysterectomy (TAH + BSO) — recommended for women who have completed family. (2) LNG-IUS + high-dose oral progestins for young women desiring fertility (under close surveillance with repeated biopsies every 3–6 months)."]','A','The WHO 2014 classification simplified hyperplasia into two categories: hyperplasia without atypia (benign), and atypical hyperplasia/EIN (precancerous). Risk factors for progression: obesity, oestrogen-only HRT, PCOS, tamoxifen use, and Lynch syndrome. After conservative treatment of EIN with complete remission, fertility treatment (IVF/IUI) should proceed promptly given risk of recurrence.','universal',true,'{year1,year2,year3,year4,year5,year6,practitioner}','Harrison''s Principles of Internal Medicine 20th Ed');
INSERT INTO questions (professions, course, topic, category, subtopic, difficulty, question_type, question_text, options, correct_answer, explanation, region, high_yield, year_level, source_reference) VALUES
('{"medicine"}','Medicine','Reproductive System & OB-GYN','Clinicals','Abnormal Uterine Bleeding','easy','flashcard','What is adenomyosis and how does it differ from endometriosis?','["Adenomyosis: endometrial glands and stroma within the myometrium, causing uterine enlargement, dysmenorrhoea, and heavy menstrual bleeding. The uterus is uniformly enlarged, tender, and boggy. TVUS: thickened myometrium, heterogeneous echotexture, myometrial cysts, linear myometrial striations. MRI: gold standard — junctional zone thickening ≥12 mm. Endometriosis: endometrial tissue outside the uterus (peritoneum, ovaries, fallopian tubes, bowel, bladder). Causes cyclical pain, dyspareunia, and infertility. They can coexist. Adenomyosis is intrinsic (uterine); endometriosis is extrinsic (pelvic)."]','A','Adenomyosis is more common in parous women in their 30s–40s. Treatment: LNG-IUS (most effective medical option), COC, GnRH analogues (temporary menopause), and hysterectomy (definitive). Focal adenomyoma can be treated with MRI-guided focused ultrasound surgery (MRgFUS). Unlike fibroids, adenomyosis cannot be easily excised surgically.','universal',true,'{year1,year2,year3,year4,year5,year6,practitioner}','Harrison''s Principles of Internal Medicine 20th Ed');
INSERT INTO questions (professions, course, topic, category, subtopic, difficulty, question_type, question_text, options, correct_answer, explanation, region, high_yield, year_level, source_reference) VALUES
('{"medicine"}','Medicine','Reproductive System & OB-GYN','Clinicals','Abnormal Uterine Bleeding','medium','flashcard','What are the medical treatment options for heavy menstrual bleeding?','["First-line (women not wanting contraception): tranexamic acid 1 g TDS during menses (antifibrinolytic — reduces loss by 50%) and/or NSAIDs (mefenamic acid 500 mg TDS — reduces loss by 25–30% and improves dysmenorrhoea). First-line (women wanting contraception/not wishing to conceive): LNG-IUS 52 mg (Mirena) — reduces loss by 80–90%, first-line NICE recommendation. Second-line: combined oral contraceptive pill (reduces loss 40–50%), cyclical oral progestins (norethisterone 5 mg TDS days 5–26), GnRH analogues (temporary medical menopause — max 6 months)."]','A','The LNG-IUS is more effective than oral medical treatments and surgical endometrial ablation in long-term RCTs. It also reduces dysmenorrhoea and provides contraception. If all medical management fails, surgical options include endometrial ablation (destroys endometrium — 80% response, 30% amenorrhoea) and hysterectomy (definitive).','universal',true,'{year1,year2,year3,year4,year5,year6,practitioner}','Harrison''s Principles of Internal Medicine 20th Ed');
INSERT INTO questions (professions, course, topic, category, subtopic, difficulty, question_type, question_text, options, correct_answer, explanation, region, high_yield, year_level, source_reference) VALUES
('{"medicine"}','Medicine','Reproductive System & OB-GYN','Clinicals','Abnormal Uterine Bleeding','hard','flashcard','What is the role of hysteroscopy in the investigation of AUB?','["Hysteroscopy allows direct visualisation of the uterine cavity using a telescope via the cervix. Diagnostic hysteroscopy: outpatient procedure (no GA); identifies polyps, fibroids (submucosal), adhesions (Asherman syndrome), foreign bodies, and focal endometrial lesions. Operative hysteroscopy: removes polyps, resects submucosal fibroids (TCRM/myomectomy), treats Asherman syndrome (adhesiolysis), and performs endometrial ablation. Hysteroscopic-guided biopsy is the gold standard for diagnosing focal endometrial pathology (superior to blind Pipelle for polyps and focal lesions). Complications: uterine perforation, fluid overload (distension medium), infection."]','A','The 2019 Cochrane review confirmed hysteroscopy has superior diagnostic accuracy over endometrial biopsy alone for intracavitary lesions. The ''see and treat'' approach (outpatient hysteroscopy + simultaneous polypectomy) is now standard of care in many centres, reducing need for separate inpatient procedures under GA.','universal',false,'{year1,year2,year3,year4,year5,year6,practitioner}','Harrison''s Principles of Internal Medicine 20th Ed');
INSERT INTO questions (professions, course, topic, category, subtopic, difficulty, question_type, question_text, options, correct_answer, explanation, region, high_yield, year_level, source_reference) VALUES
('{"medicine"}','Medicine','Reproductive System & OB-GYN','Clinicals','Abnormal Uterine Bleeding','medium','flashcard','What is Asherman syndrome and how is it managed?','["Asherman syndrome (intrauterine adhesions/synechiae): formation of fibrous adhesions within the uterine cavity, usually following uterine trauma (post-ERPC, post-myomectomy, puerperal curettage) or infection. Symptoms: hypomenorrhoea, amenorrhoea, infertility, recurrent miscarriage, and cyclic pelvic pain (haematometra from blocked outflow). Diagnosis: hysteroscopy (gold standard), saline infusion sonography, or MRI. Classification: AFS/European Society classification — minimal, moderate, severe based on extent of adhesions. Management: hysteroscopic adhesiolysis under direct vision, followed by oestrogen therapy to promote endometrial re-growth + IUD/balloon to prevent re-adhesion."]','A','Prognosis depends on severity — mild adhesions have good outcomes; dense fibromuscular adhesions (severe Asherman) have poor prognosis for fertility. Reproductive outcomes after treatment: menstrual restoration ~80%, pregnancy rate ~30–50% depending on severity. Prevention: gentle curettage technique, avoid unnecessary uterine instrumentation.','universal',false,'{year1,year2,year3,year4,year5,year6,practitioner}','Harrison''s Principles of Internal Medicine 20th Ed');
INSERT INTO questions (professions, course, topic, category, subtopic, difficulty, question_type, question_text, options, correct_answer, explanation, region, high_yield, year_level, source_reference) VALUES
('{"medicine"}','Medicine','Reproductive System & OB-GYN','Clinicals','Abnormal Uterine Bleeding','easy','flashcard','What is the most common cause of postcoital bleeding?','["The most common causes of postcoital bleeding (PCB) are: (1) Cervical ectropion (columnar epithelium on ectocervix — common in OCP users, pregnancy, and young women; fragile, bleeds easily on contact). (2) Cervicitis (Chlamydia trachomatis, gonorrhoea). (3) Cervical polyp. (4) Cervical cancer (must always be excluded — PCB is a red flag symptom). Investigation: speculum examination, cervical smear if due, STI swabs (NAAT for chlamydia and gonorrhoea), and urgent colposcopy if any cervical abnormality is seen on examination."]','A','All women with persistent postcoital bleeding or postcoital bleeding without identifiable benign cause should be referred urgently for colposcopy to exclude cervical cancer. In women over 35 with unexplained PCB, cancer must be excluded before treating ectropion. Cervical ectropion can be treated with cold coagulation or silver nitrate if causing significant symptoms.','universal',true,'{year1,year2,year3,year4,year5,year6,practitioner}','Harrison''s Principles of Internal Medicine 20th Ed');
INSERT INTO questions (professions, course, topic, category, subtopic, difficulty, question_type, question_text, options, correct_answer, explanation, region, high_yield, year_level, source_reference) VALUES
('{"medicine"}','Medicine','Reproductive System & OB-GYN','Clinicals','Abnormal Uterine Bleeding','hard','flashcard','What is the aetiology and treatment of polycystic ovary syndrome (PCOS)-related menstrual irregularity?','["PCOS causes anovulatory AUB (AUB-O) due to: chronic oestrogen stimulation without progesterone (from absent corpus luteum) → endometrial proliferation → irregular, unpredictable, and often heavy breakthrough bleeding. LH:FSH ratio elevated (>2:1), hyperandrogenaemia, insulin resistance. Unopposed oestrogen increases endometrial cancer risk. Treatment of AUB in PCOS: (1) LNG-IUS (provides progestin + treats HMB). (2) Combined OCP (regulates cycles, suppresses androgens). (3) Cyclical progestins (norethisterone 10–14 days/month). (4) Metformin (reduces insulin resistance, may restore ovulation). (5) Weight loss (most effective long-term — restores ovulation in ~50% of overweight PCOS women)."]','A','PCOS is the most common endocrinopathy in reproductive-age women (5–15%). Rotterdam criteria (2 of 3): oligo/anovulation, clinical/biochemical hyperandrogenaemia, PCOS morphology on USS (≥20 follicles per ovary or ovarian volume >10 mL). Long-term risks: T2DM (7-fold increased), endometrial cancer (3-fold), cardiovascular disease, and obstructive sleep apnoea.','universal',true,'{year1,year2,year3,year4,year5,year6,practitioner}','Harrison''s Principles of Internal Medicine 20th Ed');
INSERT INTO questions (professions, course, topic, category, subtopic, difficulty, question_type, question_text, options, correct_answer, explanation, region, high_yield, year_level, source_reference) VALUES
('{"medicine"}','Medicine','Reproductive System & OB-GYN','Clinicals','Pelvic Inflammatory Disease & STIs','easy','flashcard','What organisms cause pelvic inflammatory disease (PID)?','["PID is a polymicrobial ascending infection. Primary pathogens: (1) Chlamydia trachomatis (serovars D–K) — most common STI-related cause; causes mild/subclinical PID. (2) Neisseria gonorrhoeae — causes more severe acute PID. Together: 30–50% of cases. (3) Endogenous vaginal flora — Bacteroides, Peptostreptococcus, Gardnerella vaginalis, Streptococcus (including Group B Strep), E. coli. Mycoplasma genitalium is an emerging pathogen in PID. Viral causes: rare (e.g., herpes simplex in tubo-ovarian abscess)."]','A','Risk factors: sexual activity (multiple partners, new partner), age <25, previous PID or STI, IUD insertion in the preceding 3 weeks (then risk returns to baseline), bacterial vaginosis, and lack of barrier contraception. The cervical os is the anatomical barrier; after disruption (post-menstrual, post-surgical), ascending infection occurs.','universal',true,'{year1,year2,year3,year4,year5,year6,practitioner}','Harrison''s Principles of Internal Medicine 20th Ed');
INSERT INTO questions (professions, course, topic, category, subtopic, difficulty, question_type, question_text, options, correct_answer, explanation, region, high_yield, year_level, source_reference) VALUES
('{"medicine"}','Medicine','Reproductive System & OB-GYN','Clinicals','Pelvic Inflammatory Disease & STIs','medium','flashcard','What is the Ghana STG outpatient treatment for syndromic management of PID?','["Ghana STG outpatient PID treatment: (1) Cefixime 400 mg orally single dose (to cover gonorrhoea) + (2) Doxycycline 100 mg orally twice daily for 14 days (Chlamydia and other organisms) + (3) Metronidazole 400–500 mg orally twice daily for 14 days (anaerobes). Alternative: ceftriaxone 250 mg IM single dose instead of cefixime. Inpatient IV regimen for severe PID or TOA: ceftriaxone 1 g IV OD + doxycycline 100 mg IV/orally BD + metronidazole 500 mg IV TDS, until 24 hours clinically improved, then oral doxycycline 100 mg BD + metronidazole 400 mg TDS to complete 14 days."]','A','Syndromic management treats all likely pathogens without awaiting culture results — appropriate for resource-limited settings. Partners should be notified and treated empirically. Patients should abstain from unprotected sex for 14 days and until partners are treated. IUD can usually remain in situ if patient improves with treatment; remove if no improvement at 72 hours.','universal',true,'{year1,year2,year3,year4,year5,year6,practitioner}','Harrison''s Principles of Internal Medicine 20th Ed');
INSERT INTO questions (professions, course, topic, category, subtopic, difficulty, question_type, question_text, options, correct_answer, explanation, region, high_yield, year_level, source_reference) VALUES
('{"medicine"}','Medicine','Reproductive System & OB-GYN','Clinicals','Pelvic Inflammatory Disease & STIs','medium','flashcard','What are the stages of syphilis and their clinical features?','["Primary: painless indurated genital ulcer (chancre) at infection site + regional lymphadenopathy; appears 9–90 days post-exposure; heals spontaneously. Secondary (6–8 weeks later): generalised non-itchy maculopapular rash (including palms and soles), condylomata lata, mucous patches, generalised lymphadenopathy, systemic features (fever, malaise, alopecia, hepatitis, meningitis). Latent: asymptomatic; early (<2 years) and late (>2 years). Tertiary (years later): gummatous (soft tissue, bone), cardiovascular (aortic aneurysm — ascending aorta), and neurosyphilis (tabes dorsalis, general paresis of the insane, Argyll Robertson pupils)."]','A','All stages are caused by Treponema pallidum, a spirochaete. Diagnosis: darkfield microscopy for primary; TPHA/FTA-ABS + RPR/VDRL for serology. RPR/VDRL titers fall with treatment (useful for monitoring). Congenital syphilis: VDRL screening at booking and 28–32 weeks; treat with benzathine penicillin to prevent vertical transmission.','universal',true,'{year1,year2,year3,year4,year5,year6,practitioner}','Harrison''s Principles of Internal Medicine 20th Ed');
INSERT INTO questions (professions, course, topic, category, subtopic, difficulty, question_type, question_text, options, correct_answer, explanation, region, high_yield, year_level, source_reference) VALUES
('{"medicine"}','Medicine','Reproductive System & OB-GYN','Clinicals','Pelvic Inflammatory Disease & STIs','hard','flashcard','What is the Jarisch-Herxheimer reaction and when does it occur?','["The Jarisch-Herxheimer reaction is an acute febrile reaction occurring within 2–8 hours of initiating antibiotic treatment for spirochaetal infections (syphilis, Lyme disease, leptospirosis). Features: fever, chills, headache, myalgia, hypotension, and worsening of existing skin lesions. Mechanism: massive release of bacterial lipoproteins/endotoxins from dying spirochaetes, triggering a systemic inflammatory response. In pregnancy, it can trigger uterine contractions and fetal distress. Management: symptomatic (paracetamol, fluids, monitoring); do NOT discontinue antibiotics. In pregnant women, admit for monitoring after first penicillin dose for syphilis."]','A','The reaction is NOT an allergic reaction — it is self-limiting and resolves within 24 hours. It is most common with secondary syphilis treatment and less common with primary or late syphilis. Pretreatment with corticosteroids does not reliably prevent it. Patients should be warned before initiating treatment.','universal',true,'{year1,year2,year3,year4,year5,year6,practitioner}','Harrison''s Principles of Internal Medicine 20th Ed');
INSERT INTO questions (professions, course, topic, category, subtopic, difficulty, question_type, question_text, options, correct_answer, explanation, region, high_yield, year_level, source_reference) VALUES
('{"medicine"}','Medicine','Reproductive System & OB-GYN','Clinicals','Pelvic Inflammatory Disease & STIs','easy','flashcard','What are the clinical features of gonorrhoea in women?','["Neisseria gonorrhoeae infection in women: up to 70% are asymptomatic. Symptomatic: vaginal discharge (mucopurulent, yellow/green), dysuria, intermenstrual or post-coital bleeding, lower abdominal pain (PID), and dyspareunia. Cervicitis on examination: friable, mucopurulent discharge from os, cervical ectropion. Complications: PID, tubo-ovarian abscess, Fitz-Hugh-Curtis syndrome (perihepatitis), disseminated gonococcal infection (DGI) — septic arthritis, skin lesions, tenosynovitis. Neonatal transmission: gonococcal ophthalmia neonatorum (prevented with silver nitrate/povidone iodine eye drops at birth in endemic areas)."]','A','Diagnosis: NAAT is most sensitive (endocervical/vaginal swab or urine); culture on modified Thayer-Martin medium with antibiotic sensitivity testing is essential due to rising resistance. Treatment: ceftriaxone 500 mg IM single dose + azithromycin 1 g orally. Test of cure at 2 weeks with NAAT and culture. Partner notification is mandatory.','universal',true,'{year1,year2,year3,year4,year5,year6,practitioner}','Harrison''s Principles of Internal Medicine 20th Ed');
INSERT INTO questions (professions, course, topic, category, subtopic, difficulty, question_type, question_text, options, correct_answer, explanation, region, high_yield, year_level, source_reference) VALUES
('{"medicine"}','Medicine','Reproductive System & OB-GYN','Clinicals','Pelvic Inflammatory Disease & STIs','medium','flashcard','How is Chlamydia trachomatis treated and what is the follow-up?','["Treatment of uncomplicated Chlamydia trachomatis genital infection: (1) Doxycycline 100 mg twice daily for 7 days — first-line (superior efficacy in MGEN trial). (2) Azithromycin 1 g single dose orally — second-line (convenient but slightly lower efficacy). (3) In pregnancy: azithromycin 1 g single dose (doxycycline is contraindicated in pregnancy — affects fetal bone and tooth development). (4) Alternative in pregnancy: amoxicillin 500 mg TDS for 7 days. Test of cure is NOT recommended routinely at 3–4 weeks (high false-positive NAAT from DNA fragments). Re-test at 3–6 months for reinfection check."]','A','Chlamydia is the most common bacterial STI in sub-Saharan Africa. Partner treatment is essential (contact tracing within 60 days). Untreated, 10–40% develop PID; of those, 10–20% develop tubal infertility. Lymphogranuloma venereum (LGV) is caused by serovars L1–L3: causes inguinal granuloma, buboes, and proctitis — treated with doxycycline 100 mg BD for 21 days.','universal',true,'{year1,year2,year3,year4,year5,year6,practitioner}','Harrison''s Principles of Internal Medicine 20th Ed');
INSERT INTO questions (professions, course, topic, category, subtopic, difficulty, question_type, question_text, options, correct_answer, explanation, region, high_yield, year_level, source_reference) VALUES
('{"medicine"}','Medicine','Reproductive System & OB-GYN','Clinicals','Pelvic Inflammatory Disease & STIs','hard','flashcard','What is the syndromic approach to STI management and what are its limitations?','["Syndromic management treats STIs based on clinical syndromes (urethral discharge, vaginal discharge, genital ulcer, lower abdominal pain) without awaiting laboratory results. WHO and Ghana STG recommend it for resource-limited settings. Advantages: immediate treatment, reduces transmission, no delay waiting for culture results. Limitations: (1) Over-treatment — many patients treated who do not have the target STI. (2) Misses asymptomatic infection (majority of chlamydia and gonorrhoea in women). (3) Cannot detect antimicrobial resistance. (4) Stigma of STI treatment without confirmed diagnosis. (5) Does not allow for targeted partner notification."]','A','Syndromic management algorithms use flowcharts based on symptoms and risk assessment. The vaginal discharge algorithm is least specific (bacterial vaginosis and candidiasis are more common than STIs). Countries are moving towards syndrome + point-of-care NAAT testing to improve specificity. Syndromic management remains appropriate when laboratory infrastructure is limited.','universal',true,'{year1,year2,year3,year4,year5,year6,practitioner}','Harrison''s Principles of Internal Medicine 20th Ed');
INSERT INTO questions (professions, course, topic, category, subtopic, difficulty, question_type, question_text, options, correct_answer, explanation, region, high_yield, year_level, source_reference) VALUES
('{"medicine"}','Medicine','Reproductive System & OB-GYN','Clinicals','Pelvic Inflammatory Disease & STIs','medium','flashcard','What are the criteria for inpatient IV treatment of PID?','["Indications for inpatient IV antibiotics for PID: (1) Tubo-ovarian abscess (TOA). (2) Surgical emergency not excluded (appendicitis). (3) Pregnancy. (4) Failure to respond to oral therapy after 72 hours. (5) Severe systemic illness (high fever, vomiting, unable to take oral medications). (6) Immunosuppression. (7) Non-compliance with outpatient treatment. Inpatient IV regimen: ceftriaxone 1–2 g IV OD + doxycycline 100 mg IV BD (or orally if tolerated) + metronidazole 500 mg IV TDS. Switch to oral after 24–48 hours of clinical improvement."]','A','A 2022 Cochrane review found no significant difference in short-term outcomes between inpatient and outpatient treatment for mild-to-moderate PID. However, TOA carries risk of rupture (10% mortality if ruptured untreated) and should always be managed as inpatient with surgical backup.','universal',true,'{year1,year2,year3,year4,year5,year6,practitioner}','Harrison''s Principles of Internal Medicine 20th Ed');
INSERT INTO questions (professions, course, topic, category, subtopic, difficulty, question_type, question_text, options, correct_answer, explanation, region, high_yield, year_level, source_reference) VALUES
('{"medicine"}','Medicine','Reproductive System & OB-GYN','Clinicals','Pelvic Inflammatory Disease & STIs','easy','flashcard','What is bacterial vaginosis (BV) and how is it treated?','["BV is the most common vaginal condition in reproductive-age women. It is a polymicrobial disruption of normal vaginal flora (loss of Lactobacillus dominance) with overgrowth of Gardnerella vaginalis, Mobiluncus, Prevotella, Mycoplasma hominis. Features: thin, homogeneous, grey-white discharge with fishy odour (especially after intercourse — amine odour when alkali semen meets discharge), pH >4.5. Amsel criteria (3 of 4): clue cells on microscopy, pH >4.5, fishy odour with KOH (whiff test), thin homogeneous discharge. Treatment: metronidazole 400 mg BD for 7 days orally (or 2 g single dose) or metronidazole gel 0.75% vaginally for 5 days."]','A','BV is not an STI but is associated with sexual activity. It increases risk of preterm birth, post-surgical infection, and susceptibility to STIs (HIV, gonorrhoea, Chlamydia). Male partners do NOT require treatment (no benefit shown). Clindamycin cream vaginally is an alternative. Recurrence is common (50–80% within 12 months).','universal',true,'{year1,year2,year3,year4,year5,year6,practitioner}','Harrison''s Principles of Internal Medicine 20th Ed');
INSERT INTO questions (professions, course, topic, category, subtopic, difficulty, question_type, question_text, options, correct_answer, explanation, region, high_yield, year_level, source_reference) VALUES
('{"medicine"}','Medicine','Reproductive System & OB-GYN','Clinicals','Pelvic Inflammatory Disease & STIs','hard','flashcard','What is Mycoplasma genitalium and why is it clinically important?','["Mycoplasma genitalium (MG) is an emerging STI pathogen associated with: cervicitis, urethritis (men), PID, endometritis, infertility, and adverse pregnancy outcomes. It is the smallest self-replicating bacterium. Features: often asymptomatic; may cause mucopurulent cervicitis or urethral discharge. Diagnosis: NAAT only (not culture-able in standard labs). Treatment: (1) Azithromycin 1 g stat is NO LONGER recommended due to high resistance rates. (2) Doxycycline 100 mg BD for 7 days followed by azithromycin extended course (500 mg day 1, then 250 mg days 2–5). (3) Moxifloxacin 400 mg OD for 7–14 days for macrolide-resistant MG."]','A','MG accounts for 20–35% of PID cases not due to chlamydia or gonorrhoea. Resistance-guided therapy using NAAT with macrolide resistance mutation detection (MRM) is recommended where available. Untreated MG can cause significant tubal damage and infertility, similar to chlamydia. It is often missed as standard STI panels do not test for MG.','universal',false,'{year1,year2,year3,year4,year5,year6,practitioner}','Harrison''s Principles of Internal Medicine 20th Ed');
INSERT INTO questions (professions, course, topic, category, subtopic, difficulty, question_type, question_text, options, correct_answer, explanation, region, high_yield, year_level, source_reference) VALUES
('{"medicine"}','Medicine','Reproductive System & OB-GYN','Clinicals','Gynaecological Cancers','medium','flashcard','What is the FIGO 2018 staging for cervical cancer?','["Stage I: confined to cervix. IA = microinvasive (IA1: invasion depth ≤3 mm; IA2: 3–5 mm). IB = clinically visible or >5 mm depth (IB1: <2 cm; IB2: 2–4 cm; IB3: ≥4 cm). Stage II: beyond cervix but not pelvic wall or lower third vagina (IIA = no parametrial involvement; IIB = parametrial involvement). Stage III: extends to pelvic wall, lower third vagina, or causes hydronephrosis (IIIA = lower third vagina; IIIB = pelvic wall/hydronephrosis; IIIC = lymph node metastasis). Stage IV: beyond true pelvis or invades bladder/rectum (IVA) or distant metastases (IVB)."]','A','2018 update added IIIC to reflect lymph node involvement (IIIC1 = pelvic LN; IIIC2 = para-aortic LN), regardless of tumour size. 5-year survival: Stage IA = 93–99%; IB = 80–90%; IIB = 65–75%; III = 30–50%; IV = 5–15%. Staging is clinical ± imaging. MRI is the preferred modality for local staging; PET-CT for LN assessment.','universal',true,'{year1,year2,year3,year4,year5,year6,practitioner}','Harrison''s Principles of Internal Medicine 20th Ed');
INSERT INTO questions (professions, course, topic, category, subtopic, difficulty, question_type, question_text, options, correct_answer, explanation, region, high_yield, year_level, source_reference) VALUES
('{"medicine"}','Medicine','Reproductive System & OB-GYN','Clinicals','Gynaecological Cancers','easy','flashcard','What is the role of LLETZ (large loop excision of the transformation zone) in cervical pathology?','["LLETZ (also called LEEP — loop electrosurgical excision procedure) uses a wire loop with an electric current to excise the cervical transformation zone containing CIN (cervical intraepithelial neoplasia) or CGIN (glandular dysplasia). Indications: CIN2, CIN3, CGIN, or as a diagnostic-excisional procedure for unsatisfactory colposcopy. Advantages: outpatient procedure (local anaesthetic), provides histology specimen, low recurrence rates (90–95% success). Risks: cervical stenosis, preterm birth risk (especially with repeat excisions or excision depth >10 mm), bleeding, infection."]','A','The transformation zone (TZ) is where the squamocolumnar junction (SCJ) transitions between the squamous ectocervix and columnar endocervix — the site where HPV-related dysplasia develops. LLETZ excises Type 1 (fully ectocervical), Type 2 (partially endocervical), and Type 3 (fully endocervical) TZs — deeper excisions are needed for Type 3.','universal',true,'{year1,year2,year3,year4,year5,year6,practitioner}','Harrison''s Principles of Internal Medicine 20th Ed');
INSERT INTO questions (professions, course, topic, category, subtopic, difficulty, question_type, question_text, options, correct_answer, explanation, region, high_yield, year_level, source_reference) VALUES
('{"medicine"}','Medicine','Reproductive System & OB-GYN','Clinicals','Gynaecological Cancers','medium','flashcard','What are the risk factors for endometrial cancer?','["Type I endometrial cancer (endometrioid — 80%): driven by unopposed oestrogen. Risk factors: obesity (BMI >30 — 3-fold risk; aromatisation of androgens to oestrogen in adipose), anovulation/PCOS, nulliparity, early menarche/late menopause (prolonged oestrogen exposure), oestrogen-only HRT, tamoxifen (partial agonist on endometrium), diabetes, Lynch syndrome. Type II endometrial cancer (serous, clear cell, carcinosarcoma — 20%): oestrogen-independent; more aggressive; BRCA1 mutations, TP53 mutations."]','A','Protective factors: combined OCP (50% risk reduction — progestin opposes oestrogen), physical activity, multiparity, LNG-IUS. Most common gynaecological cancer in developed countries. Presentation: postmenopausal bleeding (in >90%). TVUS endometrial thickness >4 mm in a postmenopausal woman warrants biopsy. 5-year survival: Stage I = 85–95%; Stage IV = 5–15%.','universal',true,'{year1,year2,year3,year4,year5,year6,practitioner}','Harrison''s Principles of Internal Medicine 20th Ed');
INSERT INTO questions (professions, course, topic, category, subtopic, difficulty, question_type, question_text, options, correct_answer, explanation, region, high_yield, year_level, source_reference) VALUES
('{"medicine"}','Medicine','Reproductive System & OB-GYN','Clinicals','Gynaecological Cancers','hard','flashcard','What are the molecular subtypes of endometrial cancer and their prognostic significance?','["TCGA/ProMisE molecular classification (2013/2020): (1) POLE-ultramutated (POLE exonuclease domain mutations): hypermutated, best prognosis, may not need adjuvant treatment even at high stage. (2) MSI-high/MMR-deficient (mismatch repair deficiency — Lynch-associated): intermediate prognosis, responds to immunotherapy (pembrolizumab). (3) CN-low (copy number low/no specific molecular profile — NSMP): intermediate prognosis; includes most Type I endometrioid cancers. (4) CN-high/serous-like (TP53-mutated): worst prognosis; includes Type II cancers (serous, clear cell, carcinosarcoma)."]','A','Molecular classification is now integrated into ESGO/ESTRO/ESP 2021 treatment guidelines. POLE-mutated tumours may be spared adjuvant radiotherapy due to excellent prognosis. MSI-high/dMMR tumours qualify for pembrolizumab in recurrent/advanced disease. p53-mutated tumours require more aggressive treatment (chemoradiotherapy).','universal',false,'{year1,year2,year3,year4,year5,year6,practitioner}','Harrison''s Principles of Internal Medicine 20th Ed');
INSERT INTO questions (professions, course, topic, category, subtopic, difficulty, question_type, question_text, options, correct_answer, explanation, region, high_yield, year_level, source_reference) VALUES
('{"medicine"}','Medicine','Reproductive System & OB-GYN','Clinicals','Gynaecological Cancers','medium','flashcard','What is the role of CA-125 in ovarian cancer?','["CA-125 (cancer antigen 125) is a glycoprotein tumour marker used in ovarian cancer. Clinical uses: (1) Pre-operative assessment — combined with TVUS in the Risk of Malignancy Index (RMI) to triage adnexal masses; RMI >200 indicates specialist referral. (2) Monitoring response to chemotherapy — falling CA-125 indicates response. (3) Surveillance for recurrence after primary treatment — rising CA-125 precedes clinical recurrence by 3–6 months. Limitations: not specific — elevated in endometriosis, PID, fibroids, liver disease, peritonitis, and other cancers. Sensitivity for early-stage ovarian cancer is only 50–60%."]','A','CA-125 is most useful for high-grade serous carcinoma. Other markers: AFP and beta-hCG (germ cell tumours — dysgerminoma, yolk sac tumour, choriocarcinoma); inhibin B (granulosa cell tumours); CEA + CA19-9 (mucinous tumours). HE4 (human epididymis protein 4) combined with CA-125 in the ROMA algorithm improves sensitivity for malignancy detection.','universal',true,'{year1,year2,year3,year4,year5,year6,practitioner}','Harrison''s Principles of Internal Medicine 20th Ed');
INSERT INTO questions (professions, course, topic, category, subtopic, difficulty, question_type, question_text, options, correct_answer, explanation, region, high_yield, year_level, source_reference) VALUES
('{"medicine"}','Medicine','Reproductive System & OB-GYN','Clinicals','Gynaecological Cancers','easy','flashcard','What is the recommended cervical cancer screening interval in the UK and how does it change with age?','["UK cervical screening programme (NHSCSP): Age 25: first invitation. 25–49: every 3 years. 50–64: every 5 years. 65+: only if recent abnormal smear or not screened since age 50. Since 2019, the UK uses primary HPV testing: sample tested for high-risk HPV first; if HPV-positive, cytology is performed on the same sample (reflex cytology). If HPV-negative: no further action until next routine screen. HPV-positive + abnormal cytology: urgent colposcopy. HPV-positive + normal cytology: repeat in 12 months."]','A','Primary HPV screening has replaced cytology-first screening in the UK, Canada, Australia, Netherlands, and many other countries. It is more sensitive (~20% more) and more efficient. Women who received HPV vaccination (quadrivalent or nonavalent) still require cervical screening as the vaccines do not cover all high-risk HPV types.','universal',true,'{year1,year2,year3,year4,year5,year6,practitioner}','Harrison''s Principles of Internal Medicine 20th Ed');
INSERT INTO questions (professions, course, topic, category, subtopic, difficulty, question_type, question_text, options, correct_answer, explanation, region, high_yield, year_level, source_reference) VALUES
('{"medicine"}','Medicine','Reproductive System & OB-GYN','Clinicals','Gynaecological Cancers','hard','flashcard','What is the management of ovarian cancer and what factors predict prognosis?','["Management: (1) Surgery: primary cytoreductive surgery (PDS) — total abdominal hysterectomy + bilateral salpingo-oophorectomy + omentectomy + pelvic/para-aortic lymph node dissection + resection of all macroscopic disease (optimal debulking: residual <1 cm; complete debulking: no residual). (2) Chemotherapy: carboplatin AUC5 + paclitaxel 175 mg/m² IV every 3 weeks × 6 cycles (standard first-line). (3) Maintenance: bevacizumab (anti-VEGF); PARP inhibitors (olaparib/niraparib) for BRCA1/2 or HRD-positive tumours — significantly prolongs PFS. Prognostic factors: stage (most important), debulking outcome, histological subtype, BRCA1/2 mutation status."]','A','Neoadjuvant chemotherapy followed by interval debulking surgery (IDS) is an alternative to PDS for stage IIIC–IV disease where optimal upfront debulking is not achievable. PARP inhibitors exploit homologous recombination deficiency (HRD) — tumours unable to repair double-strand DNA breaks are killed by PARP inhibition. 5-year survival: Stage I = 90%; Stage III = 30%; Stage IV = 15%.','universal',true,'{year1,year2,year3,year4,year5,year6,practitioner}','Harrison''s Principles of Internal Medicine 20th Ed');
INSERT INTO questions (professions, course, topic, category, subtopic, difficulty, question_type, question_text, options, correct_answer, explanation, region, high_yield, year_level, source_reference) VALUES
('{"medicine"}','Medicine','Reproductive System & OB-GYN','Clinicals','Gynaecological Cancers','medium','flashcard','What is vulval intraepithelial neoplasia (VIN) and how is it managed?','["VIN is a premalignant condition of the vulva. Two types: (1) HPV-related VIN (usual type/uVIN, high-grade squamous intraepithelial lesion): affects younger women (30–50), associated with HPV 16/18, often multifocal, may regress spontaneously. (2) Differentiated VIN (dVIN): affects older women (>60), HPV-negative, arises in background of lichen sclerosus/planus, unifocal, higher malignant potential (~30% risk of invasive cancer if untreated). Treatment: wide local excision (preferred — provides histology), laser ablation (for HPV-related VIN), imiquimod 5% cream (immunomodulator for HPV-related multifocal VIN). Annual follow-up for life due to recurrence risk."]','A','HPV vaccination reduces risk of HPV-related VIN. Lichen sclerosus increases dVIN risk; adequate treatment of LS with potent topical steroids may reduce progression. Vulvectomy is reserved for invasive cancer or extensive VIN not amenable to local excision.','universal',false,'{year1,year2,year3,year4,year5,year6,practitioner}','Harrison''s Principles of Internal Medicine 20th Ed');
INSERT INTO questions (professions, course, topic, category, subtopic, difficulty, question_type, question_text, options, correct_answer, explanation, region, high_yield, year_level, source_reference) VALUES
('{"medicine"}','Medicine','Reproductive System & OB-GYN','Clinicals','Gynaecological Cancers','hard','flashcard','What are borderline ovarian tumours and how do they differ from ovarian carcinomas?','["Borderline ovarian tumours (BOTs), also called low malignant potential (LMP) tumours: epithelial ovarian neoplasms with atypical proliferation but without destructive stromal invasion. Two common types: serous (associated with KRAS/BRAF mutations) and mucinous (associated with KRAS mutations; often unilateral and large). Prognosis: excellent (10-year survival 95%+ for Stage I). Treatment: conservative surgery (unilateral salpingo-oophorectomy + frozen section intraoperatively) is appropriate for young women desiring fertility. Stage III BOTs (peritoneal implants) have a slightly worse prognosis but still excellent compared to carcinoma. Chemotherapy is NOT routinely indicated for BOTs."]','A','BOTs represent ~15% of epithelial ovarian tumours. They can recur as BOT or rarely transform to low-grade serous carcinoma. Surveillance with TVUS and CA-125 every 6 months for 5 years, then annually. Fertility after conservative surgery: IVF success rates are good, though the remaining ovary may also develop BOT. Complete staging surgery is recommended if fertility is no longer desired.','universal',false,'{year1,year2,year3,year4,year5,year6,practitioner}','Harrison''s Principles of Internal Medicine 20th Ed');
INSERT INTO questions (professions, course, topic, category, subtopic, difficulty, question_type, question_text, options, correct_answer, explanation, region, high_yield, year_level, source_reference) VALUES
('{"medicine"}','Medicine','Reproductive System & OB-GYN','Clinicals','Gynaecological Cancers','medium','flashcard','What is the HPV vaccine programme and which types does it cover?','["HPV vaccines available: (1) Cervarix (bivalent): HPV 16, 18. (2) Gardasil 4 (quadrivalent): HPV 6, 11, 16, 18. (3) Gardasil 9 (nonavalent): HPV 6, 11, 16, 18, 31, 33, 45, 52, 58. Gardasil 9 prevents ~90% of cervical cancers and ~90% of genital warts. UK programme: Gardasil 9 offered to girls AND boys aged 12–13 (school Year 8). Two doses if starting before age 15; three doses if age 15+. Catch-up to age 25 for unvaccinated individuals."]','A','HPV vaccination does not replace cervical screening — it reduces the incidence of high-risk HPV infections but does not protect against all oncogenic HPV types. Effectiveness is highest when given before sexual debut (naive to HPV). In the UK, routine HPV vaccination has led to a >90% reduction in CIN2/3 in vaccinated cohorts (NHS data). WHO aims to vaccinate 90% of girls by age 15 globally to eliminate cervical cancer.','universal',true,'{year1,year2,year3,year4,year5,year6,practitioner}','Harrison''s Principles of Internal Medicine 20th Ed');
INSERT INTO questions (professions, course, topic, category, subtopic, difficulty, question_type, question_text, options, correct_answer, explanation, region, high_yield, year_level, source_reference) VALUES
('{"medicine"}','Medicine','Reproductive System & OB-GYN','Clinicals','Male Urological Conditions','easy','flashcard','What is benign prostatic hyperplasia (BPH) and what are its LUTS?','["BPH is non-malignant enlargement of the transitional zone of the prostate due to proliferation of stromal and epithelial cells, causing bladder outflow obstruction (BOO). LUTS are divided into: (1) Obstructive/voiding symptoms: hesitancy, poor stream, straining to void, post-micturition dribble, incomplete bladder emptying, prolonged micturition. (2) Storage/irritative symptoms: frequency, urgency, nocturia, urgency incontinence. Severity quantified using International Prostate Symptom Score (IPSS): mild (0–7), moderate (8–19), severe (20–35). BPH complications: acute urinary retention, chronic retention, UTI, renal impairment, bladder stones."]','A','BPH increases in prevalence with age: 50% at 60 years, 90% at 80 years. Mechanism: DHT (dihydrotestosterone) — product of testosterone converted by 5-alpha reductase in prostate — drives prostatic cell proliferation. 5-ARIs block this. Alpha-1 receptors in prostatic stroma and bladder neck smooth muscle mediate increased tone — alpha-blockers relax this. A large prostate does not necessarily cause worse symptoms.','universal',true,'{year1,year2,year3,year4,year5,year6,practitioner}','Harrison''s Principles of Internal Medicine 20th Ed');
INSERT INTO questions (professions, course, topic, category, subtopic, difficulty, question_type, question_text, options, correct_answer, explanation, region, high_yield, year_level, source_reference) VALUES
('{"medicine"}','Medicine','Reproductive System & OB-GYN','Clinicals','Male Urological Conditions','medium','flashcard','Compare alpha-blockers and 5-alpha reductase inhibitors (5-ARIs) for BPH management.','["Alpha-1 adrenoceptor blockers (tamsulosin, alfuzosin, doxazosin, silodosin): Mechanism: relax smooth muscle in prostate and bladder neck. Onset: days. Effect on prostate size: none. Benefit: significant symptom relief (~30% IPSS reduction). Side effects: dizziness, postural hypotension (less with tamsulosin — selective alpha-1A), retrograde ejaculation (especially silodosin). 5-ARIs (finasteride, dutasteride): Mechanism: inhibit 5-alpha reductase types 1 and/or 2, reducing DHT, causing prostate volume reduction 20–30%. Onset: 3–6 months. Benefit: symptom relief + reduces AUR risk + reduces progression. Side effects: erectile dysfunction (~5%), decreased libido, ejaculatory disorders, gynaecomastia, lower PSA by 50%. Combination (MTOPS, CombAT trials): superior to monotherapy for large prostates."]','A','CombAT trial (2008): combination of tamsulosin + dutasteride reduced BPH progression and AUR risk more than either agent alone over 4 years, and was superior to tamsulosin alone in symptom improvement by 12 months. Combination therapy is recommended for men with large prostates (>40 mL) and moderate-severe LUTS.','universal',true,'{year1,year2,year3,year4,year5,year6,practitioner}','Harrison''s Principles of Internal Medicine 20th Ed');
INSERT INTO questions (professions, course, topic, category, subtopic, difficulty, question_type, question_text, options, correct_answer, explanation, region, high_yield, year_level, source_reference) VALUES
('{"medicine"}','Medicine','Reproductive System & OB-GYN','Clinicals','Male Urological Conditions','medium','flashcard','How is prostate cancer risk-stratified and what is active surveillance?','["Risk stratification (D''Amico/EAU): Low risk: PSA <10 ng/mL, Gleason ≤6 (grade group 1), cT1–T2a. Intermediate risk: PSA 10–20 ng/mL, Gleason 7 (grade group 2–3), or cT2b. High risk: PSA >20 ng/mL, Gleason 8–10 (grade group 4–5), or cT3a+. Very high risk: cT3b–T4 or N1 or Gleason 5. Active surveillance (AS): for low-risk and very low-risk localised prostate cancer — aims to delay/avoid treatment in men unlikely to die from prostate cancer. Protocol: PSA every 3–6 months, mpMRI annually, repeat biopsy at 12–18 months, then every 2–5 years. Trigger for treatment: grade progression, PSA doubling time <3 years, or patient anxiety."]','A','AS is NOT the same as watchful waiting (WW). WW is for men not fit for curative treatment — it is palliative with hormonal therapy if symptoms develop. AS actively monitors with intention to treat on progression. About 50% of men on AS eventually require treatment (curative intent) within 10–15 years. Multiple prospective trials (PRIAS, PROTECT) confirm AS is safe for low-risk PCa.','universal',true,'{year1,year2,year3,year4,year5,year6,practitioner}','Harrison''s Principles of Internal Medicine 20th Ed');
INSERT INTO questions (professions, course, topic, category, subtopic, difficulty, question_type, question_text, options, correct_answer, explanation, region, high_yield, year_level, source_reference) VALUES
('{"medicine"}','Medicine','Reproductive System & OB-GYN','Clinicals','Male Urological Conditions','hard','flashcard','What is the Gleason grading system for prostate cancer?','["Gleason grading describes the architectural pattern of prostate adenocarcinoma. Patterns 1–5 (1 = well-differentiated, 5 = undifferentiated). The Gleason score = primary pattern + secondary pattern (most common + second most common). Grade groups (2014 ISUP reform): Grade Group 1 = Gleason 3+3=6 (low risk); Grade Group 2 = Gleason 3+4=7 (intermediate, favourable); Grade Group 3 = Gleason 4+3=7 (intermediate, unfavourable); Grade Group 4 = Gleason 4+4=8 or 3+5/5+3=8; Grade Group 5 = Gleason 9–10 (high risk). Grade group is now the preferred reporting standard."]','A','Gleason 6 (grade group 1) is considered lowest-risk cancer and cannot metastasise by some definitions — supporting active surveillance. Gleason 8–10 (grade groups 4–5) has high risk of metastasis and cancer-specific mortality. Tertiary Gleason pattern 5 worsens prognosis even in a Gleason 3+4=7 score. Pattern 4 cribriform morphology is associated with higher metastatic risk.','universal',true,'{year1,year2,year3,year4,year5,year6,practitioner}','Harrison''s Principles of Internal Medicine 20th Ed');
INSERT INTO questions (professions, course, topic, category, subtopic, difficulty, question_type, question_text, options, correct_answer, explanation, region, high_yield, year_level, source_reference) VALUES
('{"medicine"}','Medicine','Reproductive System & OB-GYN','Clinicals','Male Urological Conditions','easy','flashcard','What are the complications of radical prostatectomy (RP) for prostate cancer?','["Radical prostatectomy (Wertheim/retropubic or robot-assisted laparoscopic prostatectomy — RALP): Complications: (1) Erectile dysfunction (ED): most common long-term complication; 40–80% depending on neurovascular bundle preservation. Improves with nerve-sparing technique and PDE-5 inhibitors. (2) Urinary incontinence: 5–30% at 1 year; usually stress incontinence due to sphincter disruption. Most improve with pelvic floor exercises. (3) Positive surgical margins: 10–40%; may require adjuvant radiotherapy. (4) Lymphoedema (if lymph node dissection). (5) Anastomotic stricture (1–5%). (6) Thromboembolism (perioperative)."]','A','Robot-assisted prostatectomy (RALP) has largely replaced open retropubic RP in high-income settings — associated with less blood loss, shorter hospital stay, and faster recovery. Oncological outcomes (10-year BCR-free survival) are equivalent. Urinary continence and sexual function recovery may be slightly better with RALP but evidence is mixed.','universal',true,'{year1,year2,year3,year4,year5,year6,practitioner}','Harrison''s Principles of Internal Medicine 20th Ed');
INSERT INTO questions (professions, course, topic, category, subtopic, difficulty, question_type, question_text, options, correct_answer, explanation, region, high_yield, year_level, source_reference) VALUES
('{"medicine"}','Medicine','Reproductive System & OB-GYN','Clinicals','Male Urological Conditions','medium','flashcard','What is castration-resistant prostate cancer (CRPC) and how is it treated?','["CRPC is prostate cancer that progresses despite castrate levels of testosterone (<50 ng/dL — achieved by surgical orchidectomy or LHRH agonist/antagonist). It is defined by: PSA rise on three consecutive values 1 week apart, AND/OR radiological progression, with castrate testosterone levels. Mechanisms of resistance: androgen receptor (AR) amplification/mutation, intratumoral androgen synthesis, AR splice variants (ARv7). Treatment options: (1) Abiraterone acetate + prednisolone (CYP17A1 inhibitor — blocks androgen synthesis from adrenals/tumour). (2) Enzalutamide (second-generation AR antagonist). (3) Docetaxel chemotherapy. (4) Radium-223 (alpha emitter — for bone metastases). (5) PARP inhibitors (olaparib) for BRCA-mutated mCRPC. (6) Pembrolizumab for MSI-high."]','A','CRPC is not androgen-independent — the androgen receptor remains active via alternative mechanisms. Continuing LHRH agonist maintains castrate levels and is standard even in CRPC. Median survival for mCRPC has improved from 12 months (2004) to 3–4 years (2023) with modern treatment combinations.','universal',true,'{year1,year2,year3,year4,year5,year6,practitioner}','Harrison''s Principles of Internal Medicine 20th Ed');
INSERT INTO questions (professions, course, topic, category, subtopic, difficulty, question_type, question_text, options, correct_answer, explanation, region, high_yield, year_level, source_reference) VALUES
('{"medicine"}','Medicine','Reproductive System & OB-GYN','Clinicals','Male Urological Conditions','hard','flashcard','What is the role of PSA in prostate cancer screening and what are its limitations?','["PSA (prostate-specific antigen) is a serine protease produced exclusively by prostate epithelial cells, normally found in semen. Used for PCa screening: PSA ≥4 ng/mL is abnormal (some use 3 ng/mL for men <60). Limitations: (1) Not prostate-cancer specific — elevated in BPH, prostatitis, urinary retention, bike riding, after DRE/biopsy/ejaculation. (2) Low sensitivity for early cancer (~20% of cancers have PSA <4 ng/mL). (3) Low specificity — most men with PSA 4–10 ng/mL do NOT have cancer (''grey zone''). Improvements: PSA density (PSA/prostate volume), PSA velocity (rate of rise), PSA doubling time, free:total PSA ratio (<10% more likely malignant), age-specific PSA norms, and mpMRI (PI-RADS)."]','A','The ERSPC and PLCO trials showed PSA screening reduces PCa mortality by ~20–30% but leads to significant overdiagnosis and overtreatment. Current recommendations vary: US Preventive Services Task Force recommends shared decision-making for men 55–69; EAU recommends individualised risk-based screening from 45–50 years (40 for high-risk groups). PSA should be halved when interpreting results in men on 5-ARIs.','universal',true,'{year1,year2,year3,year4,year5,year6,practitioner}','Harrison''s Principles of Internal Medicine 20th Ed');
INSERT INTO questions (professions, course, topic, category, subtopic, difficulty, question_type, question_text, options, correct_answer, explanation, region, high_yield, year_level, source_reference) VALUES
('{"medicine"}','Medicine','Reproductive System & OB-GYN','Clinicals','Male Urological Conditions','medium','flashcard','What is acute prostatitis and how does it differ from chronic prostatitis?','["Acute bacterial prostatitis: sudden onset fever, rigors, perineal/lower back pain, dysuria, urinary frequency. DRE: exquisitely tender, boggy prostate (do not massage). Organisms: E. coli (80%), Klebsiella, Proteus, Pseudomonas, Enterococcus. Treatment: ciprofloxacin 500 mg BD for 28 days (or trimethoprim 200 mg BD for 28 days) + analgesia. Hospital admission for sepsis. Chronic bacterial prostatitis: recurrent UTIs, perineal discomfort, lower urinary tract symptoms; same organisms; treat with 4–6 weeks fluoroquinolone. Chronic prostatitis/chronic pelvic pain syndrome (CP/CPPS): most common prostatitis (Type IIIa/IIIb); negative cultures; poorly understood; treated with alpha-blockers, physiotherapy, gabapentin."]','A','Acute prostatitis can be complicated by prostatic abscess (DRE shows fluctuant mass; TVUS-guided or transrectal drainage required), urosepsis, and epididymo-orchitis. PSA is always elevated in acute prostatitis — never use PSA for cancer screening during an acute episode (false positive); wait 6–8 weeks after treatment.','universal',true,'{year1,year2,year3,year4,year5,year6,practitioner}','Harrison''s Principles of Internal Medicine 20th Ed');
INSERT INTO questions (professions, course, topic, category, subtopic, difficulty, question_type, question_text, options, correct_answer, explanation, region, high_yield, year_level, source_reference) VALUES
('{"medicine"}','Medicine','Reproductive System & OB-GYN','Clinicals','Male Urological Conditions','easy','flashcard','What are the surgical options for BPH beyond medical management?','["Surgical/minimally invasive treatments for BPH: (1) TURP (transurethral resection of the prostate) — gold standard; resects obstructing prostatic tissue endoscopically. Complications: TUR syndrome (glycine absorption → hyponatraemia), retrograde ejaculation (65–90%), bleeding, erectile dysfunction (rare). (2) Holmium laser enucleation of the prostate (HoLEP) — laser enucleates and morcellates prostate; less bleeding; increasingly replacing TURP, especially for large prostates. (3) Greenlight laser photovaporisation (PVP) — suitable for men on anticoagulation. (4) Urolift — prostatic urethral lift device; preserves ejaculation; suitable for smaller prostates. (5) Rezum — water vapour (steam) therapy. (6) Open prostatectomy (Millin) — for very large prostates (>100 mL)."]','A','TURP remains the most commonly performed procedure globally. HoLEP can treat any size prostate and is becoming the gold standard in specialist centres (superior haemostasis, same-day discharge possible, very low retreatment rate). Minimally invasive options (Urolift, Rezum) are suitable for young men who wish to preserve sexual function.','universal',true,'{year1,year2,year3,year4,year5,year6,practitioner}','Harrison''s Principles of Internal Medicine 20th Ed');
INSERT INTO questions (professions, course, topic, category, subtopic, difficulty, question_type, question_text, options, correct_answer, explanation, region, high_yield, year_level, source_reference) VALUES
('{"medicine"}','Medicine','Reproductive System & OB-GYN','Clinicals','Male Urological Conditions','hard','flashcard','What are the effects of androgen deprivation therapy (ADT) on men with prostate cancer?','["ADT (LHRH agonists/antagonists or surgical orchidectomy) reduces testosterone to castrate levels (<50 ng/dL), causing: (1) Hot flushes (~80%). (2) Loss of libido and erectile dysfunction (~100% if testosterone castrate). (3) Fatigue and decreased physical performance. (4) Bone loss — osteoporosis with increased fracture risk (bone density falls 4–7% per year of ADT; bisphosphonates or denosumab are used to mitigate). (5) Metabolic syndrome — obesity, insulin resistance, dyslipidaemia, increased CVD risk. (6) Cognitive changes (possible — controversial). (7) Anaemia. (8) Gynaecomastia (from peripheral oestrogen conversion). (9) Muscle wasting (sarcopenia)."]','A','Intermittent ADT vs continuous ADT: some trials show intermittent ADT has equivalent survival with better quality of life (testosterone recovery between cycles). However, intermittent ADT is NOT recommended for high-volume metastatic disease. LHRH antagonists (degarelix, relugolix) avoid the testosterone flare seen with agonists and may have lower cardiovascular risk.','universal',true,'{year1,year2,year3,year4,year5,year6,practitioner}','Harrison''s Principles of Internal Medicine 20th Ed');
INSERT INTO questions (professions, course, topic, category, subtopic, difficulty, question_type, question_text, options, correct_answer, explanation, region, high_yield, year_level, source_reference) VALUES
('{"medicine"}','Medicine','Reproductive System & OB-GYN','Clinicals','Infertility — Clinical Management','easy','flashcard','What is the initial investigation panel for a couple presenting with infertility?','["Female investigations: (1) Day 2–4 FSH, LH, oestradiol, prolactin (ovarian reserve and ovulatory function). (2) Day 21 progesterone (confirm ovulation — >30 nmol/L indicates ovulation). (3) AMH and antral follicle count (ovarian reserve). (4) Thyroid function (TSH). (5) Hysterosalpingography or HyCoSy (tubal patency). (6) Karyotype if indicated (Turner syndrome, premature ovarian insufficiency). Male investigations: (1) Semen analysis × 2 (WHO 2021 reference values: volume ≥1.4 mL, concentration ≥16 × 10⁶/mL, total motility ≥42%, morphology ≥4%). (2) FSH, LH, testosterone (if abnormal semen analysis). (3) Karyotype and Y-microdeletion if azoospermic."]','A','Semen analysis should be repeated after 2–3 months (one spermatogenic cycle = 74 days) if abnormal. Abstinence of 2–7 days before collection. The couple should also be counselled on optimisation of lifestyle factors: maintain BMI 19–29, avoid smoking (reduces sperm quality and ovarian reserve), limit alcohol, avoid anabolic steroids.','universal',true,'{year1,year2,year3,year4,year5,year6,practitioner}','Harrison''s Principles of Internal Medicine 20th Ed');
INSERT INTO questions (professions, course, topic, category, subtopic, difficulty, question_type, question_text, options, correct_answer, explanation, region, high_yield, year_level, source_reference) VALUES
('{"medicine"}','Medicine','Reproductive System & OB-GYN','Clinicals','Infertility — Clinical Management','medium','flashcard','What are the causes of male factor infertility?','["Pre-testicular (hormonal): hypogonadotrophic hypogonadism (Kallmann syndrome — GnRH deficiency + anosmia; pituitary tumour; hyperprolactinaemia; exogenous androgen use/anabolic steroids). Testicular: primary testicular failure (Klinefelter syndrome 47,XXY — most common genetic cause of male infertility; cryptorchidism; varicocele; orchitis; torsion; chemotherapy/radiotherapy; Y-chromosome microdeletion). Post-testicular (obstructive): vasectomy; congenital absence of vas deferens (CBAVD — CFTR mutation); epididymal obstruction (post-infection); ejaculatory duct obstruction."]','A','Causes of azoospermia: obstructive (OA) — post-vasectomy, CBAVD, epididymal obstruction; FSH usually normal; sperm retrieval successful in >90%. Non-obstructive (NOA) — primary testicular failure; FSH elevated; sperm retrieval by mTESE in ~50–60%. Varicocele (dilated pampiniform plexus veins) is the most common correctable cause of male infertility; treatment by ligation or embolisation improves sperm parameters.','universal',true,'{year1,year2,year3,year4,year5,year6,practitioner}','Harrison''s Principles of Internal Medicine 20th Ed');
INSERT INTO questions (professions, course, topic, category, subtopic, difficulty, question_type, question_text, options, correct_answer, explanation, region, high_yield, year_level, source_reference) VALUES
('{"medicine"}','Medicine','Reproductive System & OB-GYN','Clinicals','Infertility — Clinical Management','medium','flashcard','What are the causes of anovulatory infertility and how are they investigated?','["WHO classification of anovulation: (1) WHO Group I (hypogonadotrophic hypogonadism): low FSH, low oestrogen; causes — Kallmann syndrome, anorexia nervosa, excessive exercise, hyperpituitarism. (2) WHO Group II (normogonadotrophic): normal/high LH, normal FSH; most common — PCOS, hyperprolactinaemia, thyroid dysfunction. (3) WHO Group III (hypergonadotrophic hypogonadism): high FSH, low oestrogen; causes — premature ovarian insufficiency (POI), Turner syndrome. Investigation: day 2–4 FSH/LH, AMH, oestradiol, prolactin, TSH, day 21 progesterone, pelvic USS (ovarian morphology, AFC)."]','A','PCOS (WHO Group II) is the most common cause of anovulatory infertility — accounts for 70–80% of WHO Group II. POI (WHO Group III) affects 1% of women under 40; causes include X-chromosome defects, autoimmune, iatrogenic (chemo/radiotherapy), and fragile X permutation. Egg donation is the only reliable option for WHO Group III infertility.','universal',true,'{year1,year2,year3,year4,year5,year6,practitioner}','Harrison''s Principles of Internal Medicine 20th Ed');
INSERT INTO questions (professions, course, topic, category, subtopic, difficulty, question_type, question_text, options, correct_answer, explanation, region, high_yield, year_level, source_reference) VALUES
('{"medicine"}','Medicine','Reproductive System & OB-GYN','Clinicals','Infertility — Clinical Management','hard','flashcard','What is ovarian hyperstimulation syndrome (OHSS) and how is it graded?','["OHSS is an iatrogenic complication of ovarian stimulation. Pathophysiology: excessive ovarian response to gonadotrophins → supraphysiological oestrogen + VEGF secretion → increased vascular permeability → fluid shift from intravascular to third space (ascites, pleural effusion, pericardial effusion). Severity: Mild (ovaries >5 cm, abdominal bloating), Moderate (TVUS ascites, nausea/vomiting, weight gain), Severe (clinical ascites, oliguria, haematocrit >45%, oocyte capture >15), Critical (tense ascites, WBC >25, haematocrit >55%, DVT/PE, ARDS, renal failure). Management: mild — analgesia, anti-emetics, oral hydration, daily weight monitoring. Severe: IV albumin, LMWH, paracentesis, cabergoline 0.5 mg/day (reduces VEGF-mediated permeability), consider freezing all embryos and cryopreservation."]','A','Prevention of OHSS: identify high-risk women (PCOS, previous OHSS, AMH >35 pmol/L, AFC >24). Strategies: GnRH antagonist protocol (allows GnRH agonist trigger — dramatically reduces OHSS risk vs HCG trigger), low-dose FSH protocols, freeze-all strategy (transfer postponed — avoids endogenous hCG from pregnancy worsening OHSS), dopamine agonist prophylaxis. OHSS is potentiated by pregnancy (endogenous hCG).','universal',true,'{year1,year2,year3,year4,year5,year6,practitioner}','Harrison''s Principles of Internal Medicine 20th Ed');
INSERT INTO questions (professions, course, topic, category, subtopic, difficulty, question_type, question_text, options, correct_answer, explanation, region, high_yield, year_level, source_reference) VALUES
('{"medicine"}','Medicine','Reproductive System & OB-GYN','Clinicals','Infertility — Clinical Management','medium','flashcard','What is the IVF process step-by-step?','["IVF process: (1) Ovarian stimulation — daily FSH injections (typically 150–300 IU/day) for 8–14 days. (2) Monitoring — serial TVUS and oestradiol to track follicular growth. (3) GnRH antagonist (cetrorelix/ganirelix) — added from day 5–6 to prevent premature LH surge. (4) Trigger — hCG 10,000 IU or GnRH agonist (antagonist protocols) when leading follicles ≥18 mm. (5) Oocyte retrieval — TVUS-guided transvaginal follicular aspiration 36 hours after trigger (under sedation). (6) Fertilisation — insemination or ICSI in embryology lab. (7) Embryo culture — 3 days (cleavage) or 5 days (blastocyst). (8) Embryo transfer — usually single blastocyst transfer (SET) to reduce multiple pregnancy. (9) Luteal phase support — progesterone pessaries/vaginal gel until week 10 of pregnancy."]','A','ICSI (intracytoplasmic sperm injection): single sperm injected directly into egg — used for severe male factor. Standard IVF: 50,000–100,000 sperm added to egg dish. Success rates decline sharply with age: live birth rate ~40% at <35 years, ~15% at 40–42 years, ~5% at 44+ years. Per-cycle live birth rate is the most meaningful success metric (not biochemical pregnancy).','universal',true,'{year1,year2,year3,year4,year5,year6,practitioner}','Harrison''s Principles of Internal Medicine 20th Ed');
INSERT INTO questions (professions, course, topic, category, subtopic, difficulty, question_type, question_text, options, correct_answer, explanation, region, high_yield, year_level, source_reference) VALUES
('{"medicine"}','Medicine','Reproductive System & OB-GYN','Clinicals','Infertility — Clinical Management','easy','flashcard','What is clomiphene citrate (clomifene) and how does it work for ovulation induction?','["Clomiphene citrate is a selective oestrogen receptor modulator (SERM) — partial agonist/antagonist. Mechanism: blocks oestrogen receptors in the hypothalamus, preventing negative feedback from oestrogen → increased GnRH pulsatility → increased FSH/LH secretion → follicular development and ovulation. Dose: 50 mg orally days 2–6 of cycle; increase to 100 mg if no ovulation. Ovulation rate ~70–80%; pregnancy rate ~40% over 6 cycles. Side effects: hot flushes, mood changes, thin endometrium, multiple pregnancy (7–10% twins), visual disturbances (discontinue if persistent). NOT recommended beyond 6 ovulatory cycles (increased risk of ovarian cancer — controversial)."]','A','Clomiphene is first-line for WHO Group II anovulation (PCOS) with BMI <30 and no other fertility factors. It is also used for unexplained infertility. Letrozole (aromatase inhibitor) is now preferred over clomiphene for PCOS ovulation induction (NEJM PPCOS II trial 2014: higher live birth rate with letrozole — 27.5% vs 19.1%). Clomiphene requires cycle monitoring with TVUS.','universal',true,'{year1,year2,year3,year4,year5,year6,practitioner}','Harrison''s Principles of Internal Medicine 20th Ed');
INSERT INTO questions (professions, course, topic, category, subtopic, difficulty, question_type, question_text, options, correct_answer, explanation, region, high_yield, year_level, source_reference) VALUES
('{"medicine"}','Medicine','Reproductive System & OB-GYN','Clinicals','Infertility — Clinical Management','hard','flashcard','What is preimplantation genetic testing (PGT) and when is it used?','["PGT is genetic analysis of embryos produced by IVF/ICSI before transfer, to select unaffected embryos. Types: (1) PGT-A (aneuploidy): screens for chromosomal number errors (most common embryo defect, especially in older women); controversial — may improve live birth rate in women ≥35 but evidence is mixed for unselected patients. (2) PGT-M (monogenic disorders): diagnoses specific single-gene disorders in embryos before transfer; used when couple are known carriers of serious conditions (e.g., cystic fibrosis, BRCA1/2, sickle cell, thalassaemia, Huntington disease). (3) PGT-SR (structural rearrangements): detects unbalanced chromosomal translocations in embryos of couples with balanced translocations who have recurrent miscarriages."]','A','PGT requires embryo biopsy at blastocyst stage (day 5–6) — 5–10 trophectoderm cells removed. It does not harm the embryo. PGT-M requires prior genetic work-up and development of a specific probe for the couple''s mutation. Ethical concerns exist around ''designer babies'' and selection of embryos for HLA matching (saviour siblings). HFEA regulates PGT in the UK.','universal',false,'{year1,year2,year3,year4,year5,year6,practitioner}','Harrison''s Principles of Internal Medicine 20th Ed');
INSERT INTO questions (professions, course, topic, category, subtopic, difficulty, question_type, question_text, options, correct_answer, explanation, region, high_yield, year_level, source_reference) VALUES
('{"medicine"}','Medicine','Reproductive System & OB-GYN','Clinicals','Infertility — Clinical Management','medium','flashcard','What is unexplained infertility and how is it managed?','["Unexplained infertility (UI): no identifiable cause found after standard investigation (patent tubes, normal semen analysis, confirmed ovulation, normal uterine cavity). Affects 25–30% of infertile couples. May represent subtle defects in fertilisation, implantation, or gamete quality not detectable by current tests. Management options: (1) Expectant management: appropriate for women <35 with <3 years infertility (cumulative conception rate ~30% in 3 years). (2) Clomiphene ± IUI (intrauterine insemination): 3–6 cycles; NICE states no benefit over expectant management for UI. (3) Superovulation (FSH) + IUI: better than clomiphene + IUI. (4) IVF: recommended after 2–3 years for women 35–40; after 1–2 years for women >40 or with declining ovarian reserve."]','A','The PPMI trial showed that in unexplained infertility, immediate IVF was not superior to expectant management over 2 years in women under 38. However, advancing age significantly reduces IVF success; women >37 with UI should not delay treatment. IVF also provides diagnostic information (fertilisation failure, embryo quality) not available from IUI.','universal',true,'{year1,year2,year3,year4,year5,year6,practitioner}','Harrison''s Principles of Internal Medicine 20th Ed');
INSERT INTO questions (professions, course, topic, category, subtopic, difficulty, question_type, question_text, options, correct_answer, explanation, region, high_yield, year_level, source_reference) VALUES
('{"medicine"}','Medicine','Reproductive System & OB-GYN','Clinicals','Infertility — Clinical Management','hard','flashcard','What is recurrent miscarriage and what are its causes?','["Recurrent miscarriage (RM) is defined as 3 or more consecutive pregnancy losses before 24 weeks (RCOG) or 2 or more consecutive losses (ESHRE/ASRM). Affects ~1% of couples. Causes: (1) Genetic: fetal chromosomal abnormalities (most common cause of sporadic miscarriage — 50–60%; in RM, fetal aneuploidy in ~50% of losses). Parental chromosomal abnormality (3–5% — balanced translocations). (2) Antiphospholipid syndrome (APS): most important treatable cause — 15% of RM; anti-cardiolipin and lupus anticoagulant antibodies cause thrombosis of placental vessels. Treat with low-dose aspirin + LMWH. (3) Uterine anomaly: bicornuate/septate uterus — septum resection improves outcomes. (4) Thrombophilia: factor V Leiden, protein C/S deficiency. (5) Hormonal: PCOS, uncontrolled thyroid disease. (6) Unexplained: 50–60% have no identifiable cause."]','A','APS management: LMWH (enoxaparin 40 mg SC OD) + aspirin 75 mg OD throughout pregnancy improves live birth rate from 10% to 70%. Investigations: karyotype (both partners), TVUS (uterine anatomy), antiphospholipid antibodies (× 2, 12 weeks apart), thrombophilia screen, thyroid function. Emotional support and early reassurance scans significantly improve outcomes even without specific treatment (the ''tender loving care'' effect).','universal',true,'{year1,year2,year3,year4,year5,year6,practitioner}','Harrison''s Principles of Internal Medicine 20th Ed');
INSERT INTO questions (professions, course, topic, category, subtopic, difficulty, question_type, question_text, options, correct_answer, explanation, region, high_yield, year_level, source_reference) VALUES
('{"medicine"}','Medicine','Reproductive System & OB-GYN','Clinicals','Infertility — Clinical Management','medium','flashcard','What is the role of laparoscopy in female infertility investigation?','["Laparoscopy is the gold standard for: (1) Diagnosing endometriosis (only definitive diagnosis — allows visualisation of peritoneal deposits, ovarian endometriomas, adhesions). (2) Assessing tubal patency (chromopertubation — injecting methylene blue through cervix and visualising spillage from fimbrial ends). (3) Diagnosing and treating pelvic adhesions (lysis of adhesions). (4) Treating endometriosis (ablation/excision of deposits, cystectomy of endometriomas). (5) Diagnosing and treating ovarian pathology (cysts, torsion). Laparoscopy is preferred over HSG when pelvic pathology is suspected (history of PID, endometriosis, pelvic pain) as it provides direct visualisation and allows simultaneous treatment."]','A','HSG is the first-line tubal patency test due to its non-invasive nature and lower cost. It has ~17% false-positive rate (tubal spasm can mimic occlusion). HyCoSy (hysterosalpingo-contrast sonography) is a TVUS-based alternative avoiding radiation. Laparoscopy is reserved for women with suspected pelvic pathology or after failed conservative management.','universal',true,'{year1,year2,year3,year4,year5,year6,practitioner}','Harrison''s Principles of Internal Medicine 20th Ed');
